insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ao poder público proporcionar assistência integral e multiprofissional à criança e ao adolescente dependentes químicos ou com problemas decorrentes do uso de drogas, protegendo sua saúde física e mental e seu bem-estar social, e promover campanhas de prevenção do uso de drogas lícitas e ilícitas.', '["Assistência integral e multiprofissional.","Campanhas de prevenção de drogas lícitas e ilícitas."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Abrange drogas lícitas e ilícitas."]'::jsonb, 'O município oferece tratamento multiprofissional ao adolescente dependente.', '["Assertiva que limita as campanhas às drogas ilícitas erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-14-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c02e387e4baefcc7457d31b449719a644b043fb58f41e162bb9f63e67e73c606'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
