insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito à liberdade, ao respeito e à dignidade como pessoas humanas em processo de desenvolvimento e como sujeitos de direitos civis, humanos e sociais garantidos na Constituição e nas leis.', '["Liberdade, respeito e dignidade.","Sujeitos de direitos civis, humanos e sociais."]'::jsonb, '["Pessoas em PROCESSO DE DESENVOLVIMENTO."]'::jsonb, 'O adolescente tem o direito de ser ouvido nas decisões que o afetam.', '["Assertiva que trata a criança como objeto de direitos erra: é sujeito de direitos."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-15' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e107ca012cdfa100d844b865200ea47cf93b5ec944aac2f24af538257b381848'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito à liberdade compreende ir, vir e estar nos logradouros públicos e espaços comunitários, ressalvadas as restrições legais; opinião e expressão; crença e culto religioso; brincar, praticar esportes e divertir-se; participar da vida familiar e comunitária sem discriminação; participar da vida política na forma da lei; e buscar refúgio, auxílio e orientação.', '["Sete aspectos da liberdade.","Locomoção, opinião, crença, lazer, convivência, vida política e busca de auxílio."]'::jsonb, '["São sete incisos."]'::jsonb, 'O adolescente pode frequentar a praça, ressalvadas as restrições legais.', '["Assertiva que exclui a participação na vida política dos aspectos da liberdade erra: está no inciso VI."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-16' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '30abb48133295fe01f36f2194167c7c0ef51c20d4f7541fd7d02da227575c519'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito ao respeito é a inviolabilidade da integridade física, psíquica e moral da criança e do adolescente, abrangendo a preservação da imagem, da identidade, da autonomia, dos valores, ideias e crenças, dos espaços e objetos pessoais.', '["Integridade física, psíquica e moral.","Imagem, identidade, autonomia, valores, espaços e objetos pessoais."]'::jsonb, '["Inclui a preservação da imagem e dos objetos pessoais."]'::jsonb, 'Divulgar a foto da criança sem proteção viola o direito ao respeito.', '["Assertiva que limita o respeito à integridade física erra: abrange também a psíquica e a moral."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-17' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '86e05c96a5077f61d8eaceb8ed007ccb7c03c68a87e1b0a82a6faf4ea490cccd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever de todos velar pela dignidade da criança e do adolescente, protegendo-os de qualquer tratamento desumano, violento, aterrorizante, vexatório ou constrangedor.', '["Dever de todos.","Proteção contra tratamento desumano, violento, aterrorizante, vexatório ou constrangedor."]'::jsonb, '["O dever é de TODOS, não só da família."]'::jsonb, 'Qualquer pessoa deve intervir diante de humilhação pública de uma criança.', '["Assertiva que restringe o dever à família erra."]'::jsonb, '[]'::jsonb, '["Art. 18-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-18' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '22c2577788e24ba7cd9d7ee4f9117d6ec1040b0320d2959d159e8299c6efab16'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito de ser educados e cuidados sem castigo físico ou tratamento cruel ou degradante, seja qual for o pretexto, pelos pais, familiares, responsáveis, agentes públicos executores de medidas socioeducativas ou qualquer pessoa encarregada de cuidar deles. Castigo físico é a ação disciplinar ou punitiva com uso da força que cause sofrimento físico ou lesão; tratamento cruel ou degradante é a conduta que humilha, ameaça gravemente ou ridiculariza.', '["Proibição de castigo físico e tratamento cruel ou degradante.","Alcança pais, familiares, responsáveis e agentes públicos.","Definições de castigo físico e de tratamento cruel."]'::jsonb, '["ATUALIZAÇÃO: a chamada Lei Menino Bernardo incluiu este artigo.","Não importa o pretexto: correção, disciplina ou educação."]'::jsonb, 'A palmada como forma de disciplina é castigo físico vedado.', '["Assertiva que admite o castigo moderado como método educativo erra."]'::jsonb, '[{"termo":"Castigo físico","significado":"Ação punitiva com força física que cause sofrimento ou lesão."}]'::jsonb, '["Art. 18-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-18-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '150b1bd405cabfb3e7012cb7b05d05396c2023142763d629b6928c05944f111a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quem usar castigo físico ou tratamento cruel ou degradante como forma de correção sujeita-se, sem prejuízo de outras sanções, a medidas aplicadas conforme a gravidade do caso: encaminhamento a programa de proteção à família, a tratamento psicológico ou psiquiátrico, a cursos ou programas de orientação, obrigação de encaminhar a criança a tratamento especializado e advertência. As medidas são aplicadas pelo Conselho Tutelar, sem prejuízo de outras providências legais.', '["Medidas aplicáveis ao agressor.","Gradação conforme a gravidade.","Aplicação pelo Conselho Tutelar."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei Menino Bernardo.","As medidas não excluem outras sanções."]'::jsonb, 'O pai que bate no filho é encaminhado a programa de orientação.', '["Assertiva que exclui as medidas se houver outra sanção aplicável erra: elas valem sem prejuízo de outras sanções."]'::jsonb, '[]'::jsonb, '["Art. 18-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-18-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3e30473c76c6197220ecbd10fe6cd3ce01c8bbdbe6832a45cafb931aa90c0dc5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito de ser criados e educados no seio da família e, excepcionalmente, em família substituta, assegurada a convivência familiar e comunitária. Quem está em acolhimento familiar ou institucional tem sua situação reavaliada, no máximo, a cada três meses, e a permanência em acolhimento não se prolonga por mais de dezoito meses, salvo comprovada necessidade que atenda ao seu interesse superior, decidida de forma fundamentada pela autoridade judiciária.', '["Criação no seio da família, excepcionalmente em família substituta.","Reavaliação a cada três meses.","Permanência máxima de dezoito meses, salvo necessidade fundamentada."]'::jsonb, '["ATUALIZAÇÃO: reavaliação a cada três meses e limite de dezoito meses vieram da Lei de Adoção.","Acolhimento é medida provisória e excepcional."]'::jsonb, 'A situação da criança acolhida é revista a cada três meses pelo juiz.', '["Assertiva que fixa em seis meses a reavaliação do acolhimento erra: é a cada três meses."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-19' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60688d53b9dd262f42ca537e4948d3d0b3e4a4ed0c5d0b4178b8521c1574c624'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A gestante ou mãe que manifeste interesse em entregar o filho para adoção, antes ou logo após o nascimento, será encaminhada à Justiça da Infância e da Juventude, onde é ouvida pela equipe interprofissional, que apresenta relatório ao juiz. O juiz pode encaminhá-la, com seu consentimento, à rede de saúde e assistência social para atendimento especializado.', '["Encaminhamento à Justiça da Infância e da Juventude.","Oitiva pela equipe interprofissional.","Atendimento especializado com consentimento."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior sobre entrega voluntária.","A mãe não pode ser constrangida."]'::jsonb, 'A gestante que não pretende ficar com o bebê procura a Vara da Infância.', '["Assertiva que obriga a mãe a manter o filho após ouvida erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-19-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8beed1bb5c0f3b4f4ac079a92b273b6538788e7f09d556445a4b440c2abf5fc8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente em acolhimento institucional ou familiar podem participar de programa de apadrinhamento, que cria vínculos externos à instituição para convivência familiar e comunitária e colaboração com seu desenvolvimento. Podem ser padrinhos pessoas maiores de dezoito anos não inscritas nos cadastros de adoção, e pessoas jurídicas podem apadrinhar para colaboração financeira, sem vínculo de guarda.', '["Apadrinhamento de crianças acolhidas.","Padrinhos maiores de dezoito anos não inscritos em cadastro de adoção.","Pessoas jurídicas podem colaborar financeiramente."]'::jsonb, '["Apadrinhamento NÃO é adoção nem guarda."]'::jsonb, 'Um casal acompanha uma criança acolhida aos finais de semana sem adotá-la.', '["Assertiva que exige a inscrição dos padrinhos no cadastro de adoção erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-19-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd8633608e6199caebda244590f1e4f0968abb72a82f03b8de7e614484c0f0582'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os filhos, havidos ou não do casamento ou por adoção, têm os mesmos direitos e qualificações, sendo proibidas designações discriminatórias relativas à filiação.', '["Igualdade entre os filhos.","Proibição de designações discriminatórias."]'::jsonb, '["Reproduz a igualdade de filiação da Constituição."]'::jsonb, 'O filho adotivo tem os mesmos direitos do filho biológico.', '["Assertiva que distingue direitos conforme a origem da filiação erra."]'::jsonb, '[]'::jsonb, '["Constituição Federal, art. 227"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-20' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e0cd5deb8b6d0753736a77f8b680fd78a6e384326ca5d8727bc2f989fb260b6d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder familiar é exercido em igualdade de condições pelo pai e pela mãe, na forma da legislação civil, e qualquer deles pode recorrer ao juiz para resolver divergência.', '["Igualdade entre pai e mãe.","Divergência resolvida pelo juiz."]'::jsonb, '["Igualdade de condições entre os genitores."]'::jsonb, 'Se os pais divergem sobre a escola, qualquer um pode pedir decisão judicial.', '["Assertiva que dá a decisão final ao pai erra: a divergência vai ao juiz."]'::jsonb, '[{"termo":"Poder familiar","significado":"Conjunto de direitos e deveres dos pais sobre os filhos menores."}]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-21' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '66f3b58bceb535d73bc9f98067edb08a290520203634cfd5bf7b76387c324a29'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos pais incumbe o dever de sustento, guarda, convivência, assistência material e afetiva e educação dos filhos menores, além de cumprir e fazer cumprir as determinações judiciais. Mãe e pai, ou responsáveis, têm direitos iguais e deveres e responsabilidades compartilhados, resguardado o direito de transmissão familiar de suas crenças e culturas.', '["Sustento, guarda, convivência, assistência e educação.","Cumprir e fazer cumprir ordens judiciais.","Responsabilidades compartilhadas."]'::jsonb, '["Inclui a assistência AFETIVA."]'::jsonb, 'Os pais devem matricular o filho na escola e acompanhar sua vida escolar.', '["Assertiva que limita o dever dos pais ao sustento material erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-22' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '93c7b5c81ae8845b125ad1fdbd7170ddafb4872c69313c5b9c71bfd17621b6a2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
