insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A falta ou a carência de recursos materiais não é motivo suficiente para a perda ou suspensão do poder familiar. Se não houver outro motivo, a criança é mantida na família de origem, que será incluída em serviços e programas oficiais de proteção e apoio. A condenação criminal do pai ou da mãe não implica destituição do poder familiar, salvo condenação por crime doloso sujeito a pena de reclusão contra quem detém igualmente o poder familiar ou contra o filho, a filha ou outro descendente.', '["Pobreza não justifica perda do poder familiar.","Família de origem incluída em programas de apoio.","Condenação criminal só leva à destituição em hipóteses específicas."]'::jsonb, '["ATUALIZAÇÃO: o §2º foi reforçado por lei posterior.","A carência de recursos NÃO basta para destituir."]'::jsonb, 'A família pobre recebe apoio do Estado e não perde o filho por isso.', '["Assertiva que autoriza a destituição do poder familiar pela mera pobreza erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-23' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b495684afadc3c714ff155eba819605eb2c4e9f1f6f8fac1a6431b95ab748c69'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A perda e a suspensão do poder familiar são decretadas judicialmente, em procedimento contraditório, nos casos previstos na legislação civil e quando houver descumprimento injustificado dos deveres do art. 22.', '["Decretação judicial.","Procedimento contraditório.","Casos da lei civil e descumprimento dos deveres."]'::jsonb, '["Só o juiz decreta, em contraditório."]'::jsonb, 'A perda do poder familiar exige processo com defesa dos pais.', '["Assertiva que permite ao Conselho Tutelar decretar a perda do poder familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 22"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-24' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '83b5d5d5aa0c683d761ced31a136b3ccc4a3aaf0e23dce5a74eac83db962ecad'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Família natural é a comunidade formada pelos pais ou qualquer deles e seus descendentes. Família extensa ou ampliada é a que vai além do núcleo de pais e filhos, formada por parentes próximos com quem a criança convive e mantém vínculos de afinidade e afetividade.', '["Família natural.","Família extensa ou ampliada com vínculos de afinidade e afetividade."]'::jsonb, '["A família extensa exige vínculos de afinidade e afetividade, além do parentesco."]'::jsonb, 'A avó com quem a criança convive integra a família extensa.', '["Assertiva que define a família extensa só pelo parentesco, sem vínculo afetivo, erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-25' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5aa7cf857aed17582becaa84302f0b6218b559ad27edabde6b00f641516d0c50'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os filhos havidos fora do casamento podem ser reconhecidos pelos pais, em conjunto ou separadamente, no termo de nascimento, por testamento, escritura ou outro documento público. O reconhecimento pode preceder o nascimento ou suceder ao falecimento do filho, se deixar descendentes.', '["Formas de reconhecimento.","Reconhecimento antes do nascimento ou após o falecimento do filho com descendentes."]'::jsonb, '["Pode ser feito por testamento."]'::jsonb, 'O pai reconhece o filho em escritura pública.', '["Assertiva que veda o reconhecimento antes do nascimento erra."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-26' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '113f845478dde0c7accf612fe35facc38672960c9cf2ab3ea472fac39529094d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O reconhecimento do estado de filiação é direito personalíssimo, indisponível e imprescritível, exercido contra os pais ou seus herdeiros, sem restrição, em segredo de Justiça.', '["Direito personalíssimo, indisponível e imprescritível.","Exercido contra pais ou herdeiros.","Segredo de Justiça."]'::jsonb, '["IMPRESCRITÍVEL."]'::jsonb, 'O filho pode pedir o reconhecimento da paternidade a qualquer tempo.', '["Assertiva que sujeita o reconhecimento de filiação a prazo prescricional erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-27' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '891c4925f9ef1c1a38c03c0cc69fb17ae9dfb6b8ae4ad1cd3dbc62e587996af9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
