insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A colocação em família substituta se dá por guarda, tutela ou adoção, independentemente da situação jurídica da criança. Sempre que possível, a criança é previamente ouvida por equipe interprofissional, e o adolescente maior de doze anos deve consentir em audiência. A preferência recai sobre a família extensa, considerando grau de parentesco e afinidade, e os grupos de irmãos devem ser colocados sob a mesma família, salvo exceções. A colocação de criança indígena ou quilombola observa suas tradições e a ouvida de equipe especializada.', '["Guarda, tutela ou adoção.","Oitiva da criança e consentimento do maior de doze anos.","Preferência pela família extensa.","Irmãos juntos.","Respeito a tradições de indígenas e quilombolas."]'::jsonb, '["Maior de doze anos: CONSENTIMENTO em audiência.","ATUALIZAÇÃO: regras de oitiva e de povos tradicionais vieram de leis posteriores."]'::jsonb, 'A adolescente de treze anos precisa consentir na colocação em família substituta.', '["Assertiva que dispensa o consentimento do maior de doze anos erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-28' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b642623a2cd69b1094b705875c054c03d4820a2a07c105898268dde74655b552'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se defere colocação em família substituta a quem revele incompatibilidade com a natureza da medida ou não ofereça ambiente familiar adequado.', '["Incompatibilidade com a medida.","Ambiente inadequado."]'::jsonb, '["Requisito de idoneidade do ambiente."]'::jsonb, 'Quem vive em ambiente violento não recebe a guarda.', '["Assertiva que dispensa a avaliação do ambiente familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-29' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f5e160b064f1f5fca19c851e07a3334734bb648a440f4085b7a3d1b180eea930'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A colocação em família substituta não admite transferência da criança ou do adolescente a terceiros ou a entidades governamentais ou não governamentais sem autorização judicial.', '["Vedada transferência sem autorização judicial."]'::jsonb, '["A transferência exige ordem do juiz."]'::jsonb, 'O guardião não pode entregar a criança a outra pessoa por conta própria.', '["Assertiva que permite ao guardião transferir a criança livremente erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-30' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3ad5775ea112f653e709e39d248ecd8d18cab8fe29542de5f823fffa23b09430'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A colocação em família substituta estrangeira é medida excepcional, admissível somente na modalidade de adoção.', '["Medida excepcional.","Apenas adoção."]'::jsonb, '["Estrangeira: SOMENTE adoção, nunca guarda ou tutela."]'::jsonb, 'Um casal estrangeiro só pode receber a criança por meio de adoção.', '["Assertiva que admite a tutela por família estrangeira erra: só a adoção."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-31' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '29c79de624689f01fd2a6c0a1f6ef3e7b393dd10b82c2a1e1be06babf6562fe4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao assumir a guarda ou a tutela, o responsável presta compromisso de bem e fielmente desempenhar o encargo, mediante termo nos autos.', '["Compromisso formal por termo nos autos."]'::jsonb, '["Termo de compromisso."]'::jsonb, 'O tutor assina o termo de compromisso no processo.', '["Assertiva que dispensa o compromisso do guardião erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-32' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0350c7af34f32ed8b4c8384b55fa0e7756072d4725d7ac657fbdc161284a00d9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A guarda obriga a prestar assistência material, moral e educacional à criança ou ao adolescente, e dá ao detentor o direito de opor-se a terceiros, inclusive aos pais. Destina-se a regularizar a posse de fato, podendo ser deferida liminar ou incidentalmente em tutela e adoção, exceto na adoção por estrangeiros, e excepcionalmente fora desses casos para situações peculiares. A guarda confere à criança a condição de dependente para todos os fins, inclusive previdenciários.', '["Assistência material, moral e educacional.","Oposição a terceiros, inclusive aos pais.","Regularização da posse de fato.","Condição de dependente."]'::jsonb, '["Pode ser oposta até aos pais.","Não cabe guarda liminar em adoção por estrangeiros."]'::jsonb, 'O avô com a guarda pode incluir o neto como dependente.', '["Assertiva que impede o guardião de se opor aos pais da criança erra."]'::jsonb, '[]'::jsonb, '["Art. 34"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-33' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c5f5eb47a4ccea8372019518ee98fb769791c706be0daa667b52aee95f14a750'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público estimula, por assistência jurídica, incentivos fiscais e subsídios, o acolhimento, sob a forma de guarda, de criança ou adolescente afastado do convívio familiar. A inclusão em acolhimento familiar tem preferência sobre o institucional, sempre com caráter temporário e excepcional. A pessoa ou casal cadastrado no programa pode receber a criança mediante guarda.', '["Estímulo ao acolhimento familiar.","Preferência pelo acolhimento familiar.","Caráter temporário e excepcional."]'::jsonb, '["Acolhimento FAMILIAR tem preferência sobre o institucional."]'::jsonb, 'A criança afastada da família é acolhida por uma família cadastrada antes de ir a um abrigo.', '["Assertiva que dá preferência ao acolhimento institucional erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-34' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8110daec4f41e3a9d3550c5daa10dd9045396acd1e7a80c783408045c26046f3'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A tutela é deferida, nos termos da lei civil, a pessoa de até dezoito anos incompletos. O deferimento da tutela pressupõe a prévia decretação da perda ou suspensão do poder familiar e implica necessariamente o dever de guarda.', '["Tutela para quem tem menos de dezoito anos.","Pressupõe perda ou suspensão do poder familiar.","Implica dever de guarda."]'::jsonb, '["ATUALIZAÇÃO: a idade foi ajustada para dezoito anos incompletos.","Tutela exige prévia perda ou suspensão do poder familiar."]'::jsonb, 'O tutor só é nomeado depois da decisão sobre o poder familiar.', '["Assertiva que dispensa a prévia perda do poder familiar para a tutela erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-36' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f1c1315ef823a620f663fda6e07b95b5268af5613ba291f02fb7de4bcc5c418f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O tutor nomeado por testamento ou documento autêntico deve, no prazo de trinta dias após a abertura da sucessão, ingressar com pedido para o controle judicial do ato, seguindo o procedimento dos arts. 165 a 170. A tutela só é deferida à pessoa indicada na disposição de última vontade se comprovado que a medida é vantajosa ao tutelando e que não há outra pessoa em melhores condições de assumi-la.', '["Prazo de trinta dias após a abertura da sucessão.","Controle judicial do ato.","Vantagem ao tutelando e inexistência de pessoa em melhores condições."]'::jsonb, '["Prazo de trinta dias."]'::jsonb, 'O tutor indicado em testamento pede o controle judicial em trinta dias.', '["Assertiva que fixa em sessenta dias o prazo do tutor testamentário erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-37' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ee7c045b7ba2c1a6899937df65d79fe3c4a65c8cdef5525f56b59b66e1533a93'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
