insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplica-se à destituição da tutela o disposto no art. 24, ou seja, é decretada judicialmente em procedimento contraditório.', '["Destituição da tutela segue o art. 24."]'::jsonb, '["Procedimento judicial e contraditório."]'::jsonb, 'O tutor negligente só é destituído por decisão judicial.', '["Assertiva que permite destituir o tutor sem processo judicial erra."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
