insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção segue as regras do Estatuto. É medida excepcional e irrevogável, só cabível depois de esgotados os recursos de manutenção da criança na família natural ou extensa. É vedada a adoção por procuração, e em caso de conflito prevalecem os direitos e interesses do adotando.', '["Excepcional e irrevogável.","Vedada a adoção por procuração.","Prevalece o interesse do adotando."]'::jsonb, '["IRREVOGÁVEL: depois de constituída, não se desfaz.","Prevalecem os interesses do adotando sobre os dos pais biológicos."]'::jsonb, 'O casal não pode adotar por meio de procurador; deve comparecer pessoalmente.', '["Assertiva que admite a adoção por procuração erra: é vedada."]'::jsonb, '[]'::jsonb, '["Art. 25"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-39' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0f94ca919772d1f6849af1feb283dd8c2c523a7712edc6e9132355870f5e45f5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
