insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção será deferida quando apresentar reais vantagens para o adotando e fundar-se em motivos legítimos.', '["Reais vantagens para o adotando.","Motivos legítimos."]'::jsonb, '["Critério central: vantagem para o adotando."]'::jsonb, 'O juiz nega a adoção feita por interesse puramente patrimonial.', '["Assertiva que dispensa a análise de vantagens para o adotando erra."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-43' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a432ffa2df1a2a30db86ccd45c6dd0da867b29663dd276735a709af74c65ecb6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
