insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção depende do consentimento dos pais ou do representante legal do adotando. O consentimento é dispensado quando os pais são desconhecidos ou foram destituídos do poder familiar. Se o adotando for maior de doze anos, também é necessário o seu consentimento.', '["Consentimento dos pais ou do representante legal.","Dispensa se pais desconhecidos ou destituídos.","Consentimento do maior de doze anos."]'::jsonb, '["Maior de doze anos: o consentimento é do PRÓPRIO adotando."]'::jsonb, 'A adolescente de catorze anos precisa consentir na própria adoção.', '["Assertiva que dispensa o consentimento do adotando maior de doze anos erra."]'::jsonb, '[]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-45' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '25bbae642ad17b5bc1ed5c653ec83248ba8ad2a9ca5578b444dfd08a7070377b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção é precedida de estágio de convivência com a criança ou adolescente, pelo prazo máximo de noventa dias, observadas a idade e as peculiaridades do caso. O estágio pode ser dispensado se o adotando já estiver sob tutela ou guarda legal do adotante tempo suficiente para avaliar o vínculo, e a simples guarda de fato não autoriza a dispensa. Há regras especiais para a adoção internacional, em que o estágio é cumprido no território nacional.', '["Estágio de convivência de até noventa dias.","Dispensa em guarda ou tutela prolongada.","Guarda de fato não dispensa o estágio.","Regras especiais para a adoção internacional."]'::jsonb, '["ATUALIZAÇÃO: prazo máximo de noventa dias fixado pela Lei de Adoção, com prorrogação em hipóteses legais.","Guarda de FATO não dispensa o estágio."]'::jsonb, 'O casal convive com a criança por noventa dias antes da sentença.', '["Assertiva que dispensa o estágio de convivência na simples guarda de fato erra."]'::jsonb, '[{"termo":"Estágio de convivência","significado":"Período de convivência prévia entre adotantes e adotando, acompanhado pela equipe técnica."}]'::jsonb, '["Art. 28"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-46' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e579bffb3b14acd42df3a5e87834a1f94aabcc235a099fce5aa7f58399bd5e39'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O vínculo da adoção constitui-se por sentença judicial, inscrita no registro civil por mandado do qual não se fornece certidão. A inscrição consigna o nome dos adotantes como pais e de seus ascendentes, e o mandado, arquivado, cancela o registro original. Nenhuma observação sobre a origem do ato pode constar nas certidões, e a sentença pode alterar o prenome do adotado a pedido do adotante ou do adotando.', '["Sentença judicial constitutiva.","Inscrição no registro civil sem certidão do mandado.","Cancelamento do registro original.","Sem observação sobre a origem na certidão."]'::jsonb, '["O vínculo nasce da SENTENÇA.","A certidão não menciona a adoção."]'::jsonb, 'A nova certidão traz os adotantes como pais, sem indicar que houve adoção.', '["Assertiva que mantém o registro original após a adoção erra: ele é cancelado."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-47' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'eb27265dde82a231a07a067a1e18229c9afd344fed4c9c232b203d6b9d5229fb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O adotado tem direito de conhecer sua origem biológica e de obter acesso irrestrito ao processo de adoção e seus incidentes após completar dezoito anos. O acesso também pode ser deferido ao adotado menor de dezoito anos, a seu pedido, com orientação e assistência jurídica e psicológica.', '["Direito de conhecer a origem biológica.","Acesso irrestrito ao processo aos dezoito anos.","Acesso antes dos dezoito, com assistência."]'::jsonb, '["Dezoito anos para o acesso irrestrito; antes, com assistência."]'::jsonb, 'Ao fazer dezoito anos, o adotado pode consultar todo o processo.', '["Assertiva que veda qualquer acesso ao processo antes dos dezoito anos erra: é possível a pedido, com assistência."]'::jsonb, '[]'::jsonb, '["Art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-48' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0333df65d90ef58b7918a2987d2f3dc3ec70a98b866a27497f67fa172debeb7f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

