select u.id, u.content_sha256, 'A morte dos adotantes não restabelece o poder familiar dos pais naturais.', '["Morte dos adotantes não restabelece o poder familiar anterior."]'::jsonb, '["Reforça a irrevogabilidade."]'::jsonb, 'Com a morte dos adotantes, os pais biológicos não retomam o poder familiar.', '["Assertiva que restabelece o poder familiar dos pais naturais com a morte dos adotantes erra."]'::jsonb, '[]'::jsonb, '["Art. 39"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-49' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '092e793c7b92dd7e76a09ac569d962562c679b8c77a40ad5afd5431ce444c6d5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
