insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se adoção internacional aquela em que o pretendente tem residência habitual em país signatário da Convenção de Haia e deseja adotar criança em outro país signatário. A adoção internacional de criança brasileira só ocorre se comprovado que a colocação em família adotiva é a solução adequada, que foram esgotadas as possibilidades de colocação em família adotiva brasileira e que, em se tratando de adolescente, ele foi consultado e preparado.', '["Residência habitual em país signatário da Convenção de Haia.","Medida de última linha: esgotadas as possibilidades nacionais.","Consulta e preparo do adolescente."]'::jsonb, '["Adoção internacional só quando esgotadas as possibilidades NACIONAIS.","Preferência de brasileiros residentes no exterior sobre estrangeiros."]'::jsonb, 'A criança só é adotada por casal de outro país depois de esgotadas as tentativas no Brasil.', '["Assertiva que dá prioridade a estrangeiros sobre candidatos nacionais erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-51' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a1a8685b59f09bcc58b1eb8dcfc963ecd9f0ece39880f719c94e62d0f90f7475'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
