on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção internacional segue o procedimento dos arts. 165 a 170, com adaptações: o interessado estrangeiro pede habilitação à Autoridade Central do país de acolhida, que emite relatório com informações sobre sua identidade e capacidade jurídica, o encaminha à Autoridade Central Estadual e esta, após análise, expede o laudo de habilitação, com validade e regras próprias de renovação.', '["Habilitação perante a Autoridade Central do país de acolhida.","Relatório e laudo de habilitação.","Validade e renovação."]'::jsonb, '["Procedimento com adaptações para a adoção internacional."]'::jsonb, 'O casal estrangeiro é habilitado pelas autoridades antes de poder adotar.', '["Assertiva que dispensa a habilitação na adoção internacional erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-52' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f0f667d9c8893b74894fcfabcee500840fbf5b754e2ab802d1eba08e81cecd6c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
