insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedado, sob pena de responsabilidade e descredenciamento, o repasse de recursos de organismos estrangeiros que intermedeiam adoção internacional a organismos nacionais ou a pessoas físicas. Eventuais repasses só podem ocorrer via Fundo dos Direitos da Criança e do Adolescente, sujeitos às deliberações do respectivo Conselho.', '["Vedado o repasse de recursos a organismos nacionais ou pessoas físicas.","Repasses somente via Fundo."]'::jsonb, '["Repasses SOMENTE via Fundo dos Direitos da Criança e do Adolescente."]'::jsonb, 'Um organismo estrangeiro só doa recursos por meio do Fundo.', '["Assertiva que permite o repasse direto a pessoas físicas erra."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-52-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9292825ca2054077591810bb54066dcdbb3a33869d2be459d268ea4d63b07743'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A adoção por brasileiro residente em país ratificante da Convenção de Haia, processada conforme a lei local e atendida a exigência da Convenção, é recepcionada automaticamente com o reingresso no Brasil. Se a exigência não foi atendida, a sentença deve ser homologada pelo Superior Tribunal de Justiça. Brasileiro residente em país não ratificante também precisa de homologação pelo STJ.', '["Recepção automática no reingresso, em país ratificante.","Homologação pelo STJ nos demais casos."]'::jsonb, '["Homologação pelo Superior Tribunal de Justiça."]'::jsonb, 'A adoção feita no exterior por brasileiro em país não ratificante é homologada pelo STJ.', '["Assertiva que dispensa a homologação em qualquer adoção feita no exterior erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-52-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '42d851088deb6405f0ea8fffea1936a0cd3b58b73e5569ee7d899af352e2134a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o Brasil é o país de acolhida, a decisão da autoridade do país de origem é conhecida pela Autoridade Central Estadual que processou a habilitação, que comunica a Autoridade Central Federal e adota as providências para o Certificado de Naturalização Provisório. A decisão só deixa de ser reconhecida se a adoção for manifestamente contrária à ordem pública ou ao interesse superior da criança.', '["Reconhecimento da decisão estrangeira pela Autoridade Central Estadual.","Certificado de Naturalização Provisório.","Recusa só se contrária à ordem pública ou ao interesse da criança."]'::jsonb, '["Recusa apenas em caso de violação manifesta."]'::jsonb, 'A decisão do país de origem é reconhecida e a criança recebe a naturalização provisória.', '["Assertiva que exige nova sentença brasileira sempre erra."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-52-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8cb2cd578a5b36fea67268b8fae10364cc1125571897930aaa89ff339eaacf7a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando o Brasil é o país de acolhida e a adoção não foi deferida no país de origem porque sua lei delega ao país de acolhida, ou a criança vem de país que não aderiu à Convenção, o processo segue as regras da adoção nacional.', '["Delegação ao país de acolhida ou país não aderente.","Aplicam-se as regras da adoção nacional."]'::jsonb, '["Segue o rito da adoção NACIONAL."]'::jsonb, 'Se o país de origem não aderiu à Convenção, aplica-se a adoção nacional.', '["Assertiva que aplica a adoção internacional mesmo sem adesão do país de origem erra."]'::jsonb, '[]'::jsonb, '["Art. 52-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-52-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '46464be3f3bfa018bd1428d30e97fcc62a9b5da1e7d865a6c15aa8b227e8a3dc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito à educação, visando ao pleno desenvolvimento da pessoa, ao preparo para a cidadania e à qualificação para o trabalho, com igualdade de condições para acesso e permanência na escola, direito de ser respeitado por educadores, de contestar critérios avaliativos, de organização em entidades estudantis e de acesso à escola pública e gratuita próxima de casa, com vagas no mesmo estabelecimento para irmãos. Os pais têm direito de ter ciência do processo pedagógico e de participar da definição das propostas educacionais.', '["Desenvolvimento, cidadania e qualificação.","Igualdade de acesso e permanência.","Direito de contestar avaliações e de organização estudantil.","Escola pública, gratuita e próxima de casa.","Ciência dos pais sobre o processo pedagógico."]'::jsonb, '["Escola próxima de casa e vaga no mesmo estabelecimento para irmãos.","Pais têm direito à ciência do processo pedagógico."]'::jsonb, 'Dois irmãos têm direito a vaga na mesma escola próxima da residência.', '["Assertiva que nega ao estudante o direito de contestar critérios de avaliação erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-53' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '37d624dc8deb74d05fa460b7cf22d281d4ac26325d5a50a32f30fd79d1e1ac5f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever das instituições de ensino, clubes, agremiações recreativas e estabelecimentos congêneres assegurar medidas de conscientização, prevenção e enfrentamento ao uso ou dependência de drogas ilícitas.', '["Dever de escolas, clubes e agremiações.","Conscientização, prevenção e enfrentamento."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Refere-se a drogas ILÍCITAS."]'::jsonb, 'A escola promove programa permanente de prevenção às drogas.', '["Assertiva que limita o dever às escolas públicas erra: alcança clubes e agremiações."]'::jsonb, '[]'::jsonb, '["Art. 14-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-53-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6e31f4e4a7f715e92f8af929c04aed7fde197c1136ab423768b237a2225433cc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever do Estado assegurar à criança e ao adolescente ensino fundamental obrigatório e gratuito, inclusive para quem não teve acesso na idade própria; progressiva extensão ao ensino médio; atendimento educacional especializado às pessoas com deficiência, preferencialmente na rede regular; atendimento em creche e pré-escola de zero a cinco anos; acesso aos níveis mais elevados do ensino, pesquisa e criação artística segundo a capacidade; ensino noturno regular; e programas suplementares de material didático, transporte, alimentação e assistência à saúde.', '["Ensino fundamental obrigatório e gratuito.","Creche e pré-escola de zero a cinco anos.","Atendimento educacional especializado, preferencialmente na rede regular.","Programas suplementares."]'::jsonb, '["Creche e pré-escola: zero a cinco anos.","ATUALIZAÇÃO: texto ajustado às emendas constitucionais sobre educação."]'::jsonb, 'O município deve oferecer vaga em creche à criança de quatro anos.', '["Assertiva que fixa o atendimento em creche apenas até três anos erra: zero a cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-54' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e56a0789927677087a27a401cfa51542c6843e66741f4be164048acf10ef4a07'
