select u.id, u.content_sha256, 'Os pais ou responsável têm a obrigação de matricular seus filhos ou pupilos na rede regular de ensino.', '["Dever de matrícula dos pais ou responsável."]'::jsonb, '["A omissão pode configurar infração administrativa e crime de abandono intelectual."]'::jsonb, 'Os pais que não matriculam o filho descumprem dever legal.', '["Assertiva que torna facultativa a matrícula na rede regular erra."]'::jsonb, '[]'::jsonb, '["Art. 249"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-55' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '01106c2f0fef88b2b3046dfaa910413337315968f9f49616191841d7cde858c2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
