insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os dirigentes de estabelecimentos de ensino fundamental devem comunicar ao Conselho Tutelar os casos de maus-tratos envolvendo alunos, reiteração de faltas injustificadas e evasão escolar esgotados os recursos escolares, elevados níveis de repetência, e negligência, abuso ou abandono.', '["Maus-tratos.","Faltas reiteradas e evasão.","Elevada repetência.","Negligência, abuso ou abandono."]'::jsonb, '["Comunicação ao CONSELHO TUTELAR.","A evasão só é comunicada depois de esgotados os recursos escolares."]'::jsonb, 'A diretora comunica ao Conselho Tutelar a evasão do aluno.', '["Assertiva que dispensa a comunicação de maus-tratos pela escola erra."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-56' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '95aa57fc625a931a99779929e483ec17d9ea041b5c9d1af315612dee9549efea'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
