insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público estimula pesquisas, experiências e novas propostas sobre calendário, seriação, currículo, metodologia, didática e avaliação, para inserir crianças e adolescentes excluídos do ensino fundamental obrigatório.', '["Estímulo a pesquisas e inovações pedagógicas.","Foco na inclusão dos excluídos do ensino fundamental."]'::jsonb, '["Voltado à inclusão de quem está fora da escola."]'::jsonb, 'O estado adapta o calendário escolar para atender alunos que trabalham.', '["Assertiva que restringe o estímulo às escolas particulares erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-57' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f641478729c119c1785a6f174fcdd37d7e9dbd459f60aa89e5643527ac2df19f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
