insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No processo educacional, respeitam-se os valores culturais, morais, éticos, artísticos e históricos próprios do contexto social da criança e do adolescente, garantindo-lhes liberdade de criação e acesso às fontes de cultura.', '["Respeito aos valores do contexto social.","Liberdade de criação e acesso à cultura."]'::jsonb, '["Valoriza o contexto social do aluno."]'::jsonb, 'A escola reconhece a cultura local no currículo.', '["Assertiva que impõe um único padrão cultural ao currículo erra."]'::jsonb, '[]'::jsonb, '["Art. 59"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-58' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6687f490ba4cef34e9365ffeaefde3d7f2275145f3a3ddaf647861f53ae6d003'
