insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os municípios, com apoio dos estados e da União, estimulam e facilitam a destinação de recursos e espaços para programações culturais, esportivas e de lazer voltadas à infância e à juventude.', '["Municípios com apoio de estados e União.","Recursos e espaços para cultura, esporte e lazer."]'::jsonb, '["Protagonismo do município."]'::jsonb, 'O município reserva uma praça para atividades esportivas infantis.', '["Assertiva que atribui o dever somente à União erra."]'::jsonb, '[]'::jsonb, '["Art. 71"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-59' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '761f6d9334ba8d31f2048c8cc66d8253edb4ee0152d670d5745e3970045fd75b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As instituições sociais públicas ou privadas que atuam com crianças e adolescentes e recebem recursos públicos devem exigir e manter certidões de antecedentes criminais de todos os colaboradores, atualizadas a cada seis meses. Os estabelecimentos educacionais e similares, mesmo sem recursos públicos, devem manter fichas cadastrais e certidões atualizadas de seus colaboradores.', '["Certidões de antecedentes de todos os colaboradores.","Atualização a cada seis meses.","Vale também para estabelecimentos educacionais sem recursos públicos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Atualização a cada seis meses."]'::jsonb, 'A escola particular mantém certidões de antecedentes de todos os professores.', '["Assertiva que fixa em um ano a atualização das certidões erra: são seis meses."]'::jsonb, '[]'::jsonb, '["Art. 70-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-59-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5e68c56f8c3d291560ef902b9f9e6ecd1be2eccff1dbd52198037f4ce9459d9c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibido qualquer trabalho a menores de quatorze anos de idade, salvo na condição de aprendiz.', '["Proibição de qualquer trabalho antes dos quatorze anos.","Exceção: aprendiz."]'::jsonb, '["Regra: nenhum trabalho antes dos quatorze anos, só como aprendiz.","Confira a legislação trabalhista e a Constituição sobre as idades mínimas vigentes."]'::jsonb, 'Um adolescente de treze anos não pode trabalhar nem como aprendiz.', '["Assertiva que admite o trabalho aos doze anos erra."]'::jsonb, '[]'::jsonb, '["Art. 62"]'::jsonb, 'under_review', 'claude'
