select u.id, u.content_sha256, 'Ao adolescente empregado, aprendiz, em regime familiar de trabalho, aluno de escola técnica ou assistido por entidade é vedado o trabalho noturno, realizado entre as vinte e duas horas de um dia e as cinco horas do dia seguinte; o trabalho perigoso, insalubre ou penoso; o realizado em locais prejudiciais à sua formação e desenvolvimento; e o realizado em horários e locais que não permitam a frequência à escola.', '["Vedado o trabalho noturno, das vinte e duas às cinco horas.","Vedado o trabalho perigoso, insalubre ou penoso.","Vedado o trabalho prejudicial à formação.","Vedado o que impeça a frequência escolar."]'::jsonb, '["Noturno: das vinte e duas às cinco horas."]'::jsonb, 'O adolescente aprendiz não pode trabalhar às vinte e três horas.', '["Assertiva que fixa o trabalho noturno das vinte às quatro horas erra: é das vinte e duas às cinco horas."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
