select u.id, u.content_sha256, 'O poder público, por meio do órgão competente, regula as diversões e espetáculos públicos, informando sobre sua natureza, as faixas etárias a que não se recomendem e os locais e horários em que sua apresentação seja inadequada. Os responsáveis devem afixar, em lugar visível, à entrada, informação destacada sobre a natureza do espetáculo e a faixa etária.', '["Regulação pelo poder público.","Informação sobre faixa etária e natureza.","Afixação visível à entrada."]'::jsonb, '["A classificação é INDICATIVA em regra, mas obedece à regulação."]'::jsonb, 'O cinema afixa a faixa etária na entrada da sala.', '["Assertiva que dispensa a informação visível sobre a faixa etária erra."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-74' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd6c161c207322df8a750fffb1700308da3b4d75c9e01152128666d66c725b4e0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
