on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Toda criança ou adolescente tem acesso às diversões e espetáculos públicos classificados como adequados à sua faixa etária. As crianças menores de dez anos só podem ingressar e permanecer nos locais quando acompanhadas dos pais ou responsável.', '["Acesso aos espetáculos adequados à idade.","Menores de dez anos só acompanhados."]'::jsonb, '["Menores de dez anos: acompanhados dos pais ou responsável."]'::jsonb, 'A criança de oito anos só entra no cinema com um responsável.', '["Assertiva que fixa em doze anos a idade para ingresso desacompanhado erra: menores de dez anos precisam de acompanhante."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-75' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '047e8c93f771c1e812c2d1b19b594e91beccd15f6581e47e57a5e9053a48a00e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
