insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As emissoras de rádio e televisão só exibem, no horário recomendado para o público infantojuvenil, programas com finalidades educativas, artísticas, culturais e informativas. Nenhum espetáculo é apresentado ou anunciado sem aviso de sua classificação.', '["Programação adequada no horário infantojuvenil.","Aviso prévio de classificação."]'::jsonb, '["Aviso de classificação antes da exibição."]'::jsonb, 'A TV exibe a classificação antes do programa.', '["Assertiva que permite qualquer programa no horário infantojuvenil erra."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-76' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '902b050576b32204cd721c37c821501abf01eb73ac541c187b28444b0c40c066'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
