insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quem explora venda ou aluguel de fitas de programação em vídeo deve cuidar para que não haja venda ou locação em desacordo com a classificação atribuída. As fitas devem exibir, no invólucro, informação sobre a natureza da obra e a faixa etária.', '["Respeito à classificação na venda e locação.","Informação no invólucro."]'::jsonb, '["Dispositivo histórico, aplicável por analogia a mídias."]'::jsonb, 'A locadora não aluga filme impróprio a um adolescente.', '["Assertiva que dispensa a informação da faixa etária no invólucro erra."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-77' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b5dc4d5898a2f5c78f01136c2e0294b6a2a3a4b276f526efabbe62a50c25863b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As revistas e publicações com material impróprio ou inadequado a crianças e adolescentes devem ser comercializadas em embalagem lacrada, com advertência de seu conteúdo. As editoras cuidam para que capas com mensagens pornográficas ou obscenas sejam protegidas com embalagem opaca.', '["Embalagem lacrada e advertência.","Embalagem opaca para capas obscenas."]'::jsonb, '["Obrigação também das editoras."]'::jsonb, 'A revista adulta é vendida lacrada em embalagem opaca.', '["Assertiva que dispensa a embalagem lacrada para publicações impróprias erra."]'::jsonb, '[]'::jsonb, '["Art. 79"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-78' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '80b5f82ed5f7c981a916a731a8eaa259ea14644ae5fe53f1ea04ee96eae7000b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As revistas e publicações destinadas ao público infantojuvenil não podem conter ilustrações, fotografias, legendas, crônicas ou anúncios de bebidas alcoólicas, tabaco, armas e munições, e devem respeitar os valores éticos e sociais da pessoa e da família.', '["Proibição de publicidade de álcool, tabaco, armas e munições.","Respeito aos valores da família."]'::jsonb, '["Vale para publicações destinadas ao público infantojuvenil."]'::jsonb, 'A revista para adolescentes não pode trazer anúncio de cerveja.', '["Assertiva que permite anúncio de tabaco em revista infantojuvenil erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-79' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '101bd6b552b504924390110c7276834a6a6ee6edf93d0c1f31042165114e2247'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
