insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os responsáveis por estabelecimentos de bilhar, sinuca ou congênere ou por casas de jogos, isto é, as que realizem apostas, ainda que eventualmente, cuidam para que não entrem nem permaneçam crianças e adolescentes, afixando aviso para orientação do público.', '["Vedada a entrada e permanência de crianças e adolescentes.","Aviso afixado."]'::jsonb, '["Casas de jogos: aposta, ainda que eventual."]'::jsonb, 'A casa de sinuca afixa o aviso de proibição a menores.', '["Assertiva que permite a permanência de adolescentes em casas de jogos desde que acompanhados erra."]'::jsonb, '[]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-80' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0af80d781ad3015ecd487f6a5eda37b0434a2363a8fd38f0f32c5fa7326e398a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
