insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É proibida a hospedagem de criança ou adolescente em hotel, motel, pensão ou estabelecimento congênere, salvo se autorizado ou acompanhado pelos pais ou responsável.', '["Vedada a hospedagem desacompanhada.","Exceção: autorização ou acompanhamento dos pais ou responsável."]'::jsonb, '["Autorização OU acompanhamento afasta a vedação."]'::jsonb, 'O adolescente com autorização dos pais pode se hospedar no hotel.', '["Assertiva que proíbe a hospedagem mesmo acompanhada pelos pais erra."]'::jsonb, '[]'::jsonb, '["Art. 250"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-82' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bd73448d157a875198f9f79e1c65c9367d212058101e8ebe55bb843aa7a59843'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma criança ou adolescente menor de dezesseis anos pode viajar para fora da comarca onde reside desacompanhado dos pais ou responsáveis sem expressa autorização judicial. A autorização é dispensada em comarca contígua da mesma unidade da Federação ou região metropolitana, ou quando acompanhado de ascendente ou colateral maior até o terceiro grau, ou de pessoa maior expressamente autorizada pelo pai, mãe ou responsável.', '["Menor de dezesseis anos precisa de autorização para sair da comarca.","Dispensas: comarca contígua, parente maior, pessoa autorizada.","Autorização judicial pode ser válida por até dois anos."]'::jsonb, '["Regra aplica-se ao menor de dezesseis anos.","Dispensas em comarcas contíguas e com acompanhante autorizado."]'::jsonb, 'A adolescente de quinze anos viaja com a tia maior, comprovado o parentesco.', '["Assertiva que exige autorização judicial para qualquer viagem de adolescente erra: há dispensas."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-83' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8c9ae2b21d68dc209d0859663c152e607025fced57d077e93ff96072ae5a5437'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na viagem ao exterior, a autorização é dispensável se a criança ou o adolescente estiver acompanhado de ambos os pais ou responsável, ou viajar com um dos pais autorizado expressamente pelo outro por documento com firma reconhecida.', '["Dispensa se acompanhado de ambos os pais ou responsável.","Dispensa se com um dos pais e autorização do outro com firma reconhecida."]'::jsonb, '["Firma reconhecida na autorização do outro genitor."]'::jsonb, 'A criança viaja com a mãe e leva autorização do pai com firma reconhecida.', '["Assertiva que dispensa a firma reconhecida na autorização do outro genitor erra."]'::jsonb, '[]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-84' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd47a992f2ebbff03864bf6f5a1ea91160c0fb73916d53d5b4aaf8c49f325ad04'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sem prévia e expressa autorização judicial, nenhuma criança ou adolescente nascido em território nacional pode sair do País em companhia de estrangeiro residente ou domiciliado no exterior.', '["Autorização judicial prévia e expressa.","Estrangeiro residente ou domiciliado no exterior."]'::jsonb, '["Exige autorização JUDICIAL, não só dos pais."]'::jsonb, 'A criança brasileira só viaja com estrangeiro residente fora com autorização do juiz.', '["Assertiva que dispensa a autorização judicial se os pais concordarem erra."]'::jsonb, '[]'::jsonb, '["Art. 84"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-85' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f45e0c42aee2e35589eb9e0cb949f1ae09d4e92fa668fc2f6dfbba4fb3003ed4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A política de atendimento dos direitos da criança e do adolescente é feita por um conjunto articulado de ações governamentais e não governamentais da União, dos estados, do Distrito Federal e dos municípios.', '["Ações articuladas.","Governamentais e não governamentais.","Todos os entes federativos."]'::jsonb, '["Política ARTICULADA entre os entes e a sociedade."]'::jsonb, 'Município, estado e ONGs atuam juntos em um programa de acolhimento.', '["Assertiva que atribui a política de atendimento somente à União erra."]'::jsonb, '[]'::jsonb, '["Art. 87"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-86' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6d7658fded3786eefe3742a9ccd93849b24a48d9b739027d10d10b6308d95b69'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São linhas de ação da política de atendimento as políticas sociais básicas; os serviços e programas de assistência social; os serviços especiais de prevenção e atendimento médico e psicossocial às vítimas de negligência, maus-tratos, exploração, abuso, crueldade e opressão; a proteção jurídico-social por entidades de defesa dos direitos; e a política de estímulo ao acolhimento familiar, entre outras.', '["Políticas sociais básicas.","Assistência social.","Atendimento às vítimas de violência.","Proteção jurídico-social.","Estímulo ao acolhimento familiar."]'::jsonb, '["ATUALIZAÇÃO: o rol foi ampliado por leis posteriores sobre busca de desaparecidos e acolhimento familiar."]'::jsonb, 'O município mantém serviço psicossocial para vítimas de abuso.', '["Assertiva que restringe as linhas de ação às políticas de saúde erra."]'::jsonb, '[]'::jsonb, '["Art. 86"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-87' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2dd63955f62b3a567e5be72a1dafb2bdc61d9f58d41d412c873f237dbbcd2bbd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São diretrizes da política de atendimento a municipalização do atendimento; a criação de conselhos municipais, estaduais e nacional dos direitos da criança e do adolescente, órgãos deliberativos e controladores com participação popular paritária; a criação e manutenção de programas específicos; a manutenção de fundos vinculados aos conselhos; a integração operacional dos órgãos do Judiciário, Ministério Público, Defensoria, segurança pública e assistência social; e a mobilização da opinião pública.', '["Municipalização.","Conselhos deliberativos e controladores com participação paritária.","Fundos vinculados aos conselhos.","Integração operacional dos órgãos."]'::jsonb, '["Conselhos de direitos são deliberativos e controladores, com participação PARITÁRIA.","Municipalização é a primeira diretriz."]'::jsonb, 'O Conselho Municipal dos Direitos delibera sobre o uso do fundo.', '["Assertiva que torna os conselhos de direitos meramente consultivos erra: são deliberativos e controladores."]'::jsonb, '[{"termo":"Municipalização","significado":"Descentralização do atendimento para o nível municipal."}]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-88' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd8767382a3df86b3d492b662cea4cbc5eed9c42d1cd8dbd3d26d8688c09da6f1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
