insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A função de membro dos Conselhos dos Direitos da Criança e do Adolescente é considerada de interesse público relevante e não é remunerada. Cada ente da Federação disciplina, por lei, a perda da função de conselheiro, respeitado o art. 89-A.', '["Interesse público relevante.","Não remunerada.","Perda da função disciplinada em lei de cada ente."]'::jsonb, '["Conselheiro de DIREITOS não é remunerado; o conselheiro tutelar é remunerado.","Não confundir Conselho de Direitos com Conselho Tutelar."]'::jsonb, 'O representante da sociedade civil no Conselho de Direitos atua sem remuneração.', '["Assertiva que prevê remuneração aos membros do Conselho dos Direitos erra."]'::jsonb, '[]'::jsonb, '["Art. 89-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-89' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b974d62038ab12a0c747077bd583ce117233868d1f2405d50623f6eb6b7294cd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São deveres fundamentais dos membros dos Conselhos dos Direitos promover a defesa dos direitos das crianças e dos adolescentes, respeitar a Constituição e as leis, zelar pelo prestígio do Conselho e exercer a função com dignidade e respeito aos pares, entre outros. A violação desses deveres pode levar à perda da função, na forma da lei de cada ente.', '["Defesa dos direitos da infância.","Cumprimento da Constituição e das leis.","Zelo pelo prestígio do Conselho."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O conselheiro que age com improbidade pode perder a função.', '["Assertiva que dispensa deveres funcionais dos conselheiros de direitos erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-89-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5cfe735b4997a4511c1b2b4a8eecce99bb1ddefdc90a1c835dcae8611e942dca'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de atendimento são responsáveis pela manutenção das próprias unidades e pelo planejamento e execução de programas de proteção e socioeducativos, em regime de orientação e apoio sociofamiliar, apoio socioeducativo em meio aberto, colocação familiar, acolhimento institucional, prestação de serviços à comunidade, liberdade assistida, semiliberdade e internação. Os programas devem ser inscritos no Conselho Municipal dos Direitos.', '["Responsabilidade pela manutenção e execução dos programas.","Oito regimes de atendimento.","Inscrição dos programas no Conselho Municipal."]'::jsonb, '["Oito regimes: de orientação sociofamiliar à internação.","ATUALIZAÇÃO: acolhimento institucional substituiu a antiga referência a abrigo."]'::jsonb, 'A ONG inscreve seu programa de liberdade assistida no Conselho Municipal.', '["Assertiva que dispensa a inscrição dos programas no Conselho Municipal erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-90' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a95d5501eec7d28d07f5c8744cf359a86a793d08551f6f8fd6d1b3cf364b29a8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades não governamentais só podem funcionar depois de registradas no Conselho Municipal dos Direitos da Criança e do Adolescente, que comunica o registro ao Conselho Tutelar e à autoridade judiciária. O registro é negado à entidade que não ofereça instalações adequadas, não apresente plano de trabalho compatível, esteja irregularmente constituída ou tenha em seus quadros pessoas inidôneas.', '["Registro prévio no Conselho Municipal.","Comunicação ao Conselho Tutelar e à autoridade judiciária.","Hipóteses de negativa do registro."]'::jsonb, '["Registro no Conselho MUNICIPAL, com comunicação à Justiça.","Registro vale por prazo limitado e deve ser renovado."]'::jsonb, 'A ONG sem instalações adequadas tem o registro negado.', '["Assertiva que atribui o registro de entidades não governamentais ao Conselho Tutelar erra."]'::jsonb, '[]'::jsonb, '["Art. 90"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-91' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0fbb9bf34cfaab17fe40f6ba5da6ec2a7345eeeb119e67069d75dfe9ab734eab'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de acolhimento familiar ou institucional adotam como princípios a preservação dos vínculos familiares e promoção da reintegração familiar; a integração em família substituta quando esgotados os recursos de manutenção na família natural ou extensa; o atendimento personalizado e em pequenos grupos; a co-educação; o não desmembramento de grupos de irmãos; a participação na vida da comunidade local; e a preparação gradativa para o desligamento.', '["Preservação dos vínculos e reintegração familiar.","Atendimento personalizado em pequenos grupos.","Não desmembramento de irmãos.","Preparação gradativa para o desligamento."]'::jsonb, '["Irmãos não devem ser separados.","Reintegração familiar vem antes da família substituta."]'::jsonb, 'Irmãos acolhidos permanecem na mesma entidade.', '["Assertiva que permite desmembrar grupos de irmãos livremente erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-92' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b8e16de273d848ba5f45e2eb138a60c3eab634bcf16d45017fddd05fdad5d43a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de acolhimento institucional podem, em caráter excepcional e de urgência, acolher crianças e adolescentes sem prévia determinação da autoridade competente, comunicando o fato em até vinte e quatro horas ao Juiz da Infância e da Juventude, sob pena de responsabilidade. Recebida a comunicação, o juiz, ouvido o Ministério Público, adota as medidas necessárias.', '["Acolhimento excepcional e urgente sem ordem prévia.","Comunicação ao juiz em até vinte e quatro horas.","Responsabilidade em caso de omissão."]'::jsonb, '["Prazo de vinte e quatro horas para comunicar."]'::jsonb, 'A entidade acolhe a criança em risco à noite e avisa o juiz no dia seguinte.', '["Assertiva que fixa em setenta e duas horas o prazo de comunicação erra: são vinte e quatro horas."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-93' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3f3500d9ddf9c2e5269ddaa6e4a057fa99e23241ada8cfbf3df29d7c73e50747'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As entidades de internação têm obrigações como observar os direitos e garantias do adolescente, não restringir direito que não tenha sido restringido na decisão, oferecer atendimento personalizado em pequenas unidades, preservar a identidade e oferecer ambiente de respeito e dignidade, restabelecer e preservar os vínculos familiares, manter programas de educação, saúde e lazer, e comunicar à autoridade judiciária eventual fuga, entre outras.', '["Respeito aos direitos do adolescente.","Não restringir direitos além da decisão.","Atendimento personalizado em pequenas unidades.","Preservação dos vínculos familiares."]'::jsonb, '["Rol exemplificativo, indicado por \"entre outras\".","O descumprimento sujeita a entidade às medidas do art. 97."]'::jsonb, 'A unidade de internação mantém escolarização e atividades de lazer.', '["Assertiva que permite restringir direitos além da decisão de internação erra."]'::jsonb, '[]'::jsonb, '["Art. 97"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-94' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8eec197429d4f0d335b472e667927be334ca2b4f786c88ea5755c4339ce94165'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
