insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Considera-se ato infracional a conduta descrita como crime ou contravenção penal.', '["Ato infracional = crime ou contravenção penal praticada por criança ou adolescente."]'::jsonb, '["Vocabulário próprio: não se fala em crime do adolescente, e sim em ato infracional."]'::jsonb, 'O furto praticado por adolescente é ato infracional.', '["Assertiva que trata o ato infracional como crime do adolescente erra na terminologia legal."]'::jsonb, '[{"termo":"Ato infracional","significado":"Conduta descrita como crime ou contravenção penal."}]'::jsonb, '["Art. 104"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-103' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd4b50f3a37472aa39087ed890a69a160637b25a9d6c42694ccbb77b955094567'
