insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum adolescente será privado de sua liberdade senão em flagrante de ato infracional ou por ordem escrita e fundamentada da autoridade judiciária competente. O adolescente tem direito à identificação dos responsáveis pela sua apreensão e deve ser informado de seus direitos.', '["Flagrante ou ordem escrita e fundamentada.","Identificação dos responsáveis pela apreensão.","Informação sobre os direitos."]'::jsonb, '["Apenas FLAGRANTE ou ORDEM JUDICIAL escrita e fundamentada."]'::jsonb, 'O adolescente é apreendido em flagrante e informado de seus direitos.', '["Assertiva que permite apreensão por ordem verbal da autoridade policial erra."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-106' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6bced24b17c69ff33c0ceb6766f42138182b9fac47bf4a5d7a4679dcee367cc6'
