insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O adolescente civilmente identificado não é submetido a identificação compulsória pelos órgãos policiais, de proteção e judiciais, salvo para confrontação, havendo dúvida fundada.', '["Sem identificação compulsória se já identificado civilmente.","Exceção: confrontação em caso de dúvida fundada."]'::jsonb, '["Exceção só para confrontação, havendo dúvida fundada."]'::jsonb, 'O adolescente com documento não é fichado pela polícia.', '["Assertiva que obriga a identificação criminal de todo adolescente apreendido erra."]'::jsonb, '[]'::jsonb, '["Art. 106"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-109' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '48d663cc024bd51f596cb9bdef6987142b47767ee901e9a81628e3cc7ca1083c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
