insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum adolescente será privado de sua liberdade sem o devido processo legal.', '["Devido processo legal."]'::jsonb, '["Garantia constitucional aplicada ao adolescente."]'::jsonb, 'A internação como medida socioeducativa só ocorre depois do processo.', '["Assertiva que dispensa o devido processo na apuração do ato infracional erra."]'::jsonb, '[]'::jsonb, '["Art. 111"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-110' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2853d51817ef530fb7c829e2f51dff13ac70937657a00b114b2ea5263b6f10ac'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
