insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São asseguradas ao adolescente, entre outras, as garantias de pleno e formal conhecimento da atribuição do ato infracional, igualdade na relação processual com direito de confrontar vítimas e testemunhas e produzir provas, defesa técnica por advogado, assistência judiciária gratuita aos necessitados, direito de ser ouvido pessoalmente e direito de solicitar a presença de seus pais ou responsável em qualquer fase do procedimento.', '["Conhecimento formal do ato.","Igualdade processual.","Defesa técnica por advogado.","Assistência judiciária gratuita.","Oitiva pessoal e presença dos pais."]'::jsonb, '["Defesa técnica por advogado é GARANTIA do adolescente."]'::jsonb, 'O adolescente é ouvido pessoalmente e acompanhado de advogado.', '["Assertiva que dispensa a defesa técnica na apuração do ato infracional erra."]'::jsonb, '[]'::jsonb, '["Art. 110"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-111' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '494dc6f7e8c5adaa267150911d9de006d26730f202a65654719fea15d429a00a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a prática de ato infracional, a autoridade pode aplicar ao adolescente advertência, obrigação de reparar o dano, prestação de serviços à comunidade, liberdade assistida, inserção em regime de semiliberdade, internação em estabelecimento educacional ou qualquer das medidas de proteção do art. 101, incisos I a VI. A medida leva em conta a capacidade de cumpri-la, as circunstâncias e a gravidade da infração. Em hipótese alguma e sob pretexto algum será admitida a prestação de trabalho forçado, e os adolescentes portadores de doença ou deficiência mental recebem tratamento individual e especializado.', '["Seis medidas socioeducativas e as protetivas.","Capacidade de cumprimento, circunstâncias e gravidade.","Vedado o trabalho forçado.","Tratamento especializado para doença ou deficiência mental."]'::jsonb, '["Rol de medidas socioeducativas: advertência, reparação, serviços, liberdade assistida, semiliberdade e internação.","Trabalho forçado é vedado em qualquer hipótese."]'::jsonb, 'O juiz aplica prestação de serviços à comunidade ao adolescente que cometeu ato de menor gravidade.', '["Assertiva que admite o trabalho forçado como medida socioeducativa erra."]'::jsonb, '[{"termo":"Medida socioeducativa","significado":"Resposta estatal ao ato infracional do adolescente, com finalidade pedagógica."}]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-112' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1d7c522df45e61c74ef8d0f3543c23f46943a1ae9ac7f44aa6fe9b5154a44080'
