insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se às medidas socioeducativas as regras dos arts. 99 e 100, ou seja, a aplicação isolada ou cumulativa, a substituição a qualquer tempo e os princípios que regem as medidas.', '["Arts. 99 e 100 aplicam-se às socioeducativas."]'::jsonb, '["Mesmos princípios das medidas de proteção."]'::jsonb, 'O juiz pode substituir uma medida socioeducativa por outra mais adequada.', '["Assertiva que afasta os princípios do art. 100 das medidas socioeducativas erra."]'::jsonb, '[]'::jsonb, '["Arts. 99 e 100"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-113' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'aaacfcb8a5ba3008c77c68ed390c2abba60a533d5be1e3021c0bbd102a1c0673'
