insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em ato infracional com reflexos patrimoniais, a autoridade pode determinar que o adolescente restitua a coisa, promova o ressarcimento do dano ou, por outra forma, compense o prejuízo da vítima. Havendo manifesta impossibilidade, a medida pode ser substituída por outra adequada.', '["Restituição, ressarcimento ou compensação.","Substituição se houver impossibilidade."]'::jsonb, '["Cabe apenas em atos com reflexo patrimonial."]'::jsonb, 'O adolescente que danificou o bem repara o prejuízo da vítima.', '["Assertiva que impede a substituição da medida de reparação erra."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-116' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '801e7802c835d6bb726e2a4211ca718e55d088b3a5661320ab14efe79c6d257f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A prestação de serviços comunitários consiste em tarefas gratuitas de interesse geral, por período não superior a seis meses, junto a entidades assistenciais, hospitais, escolas e estabelecimentos congêneres, ou em programas comunitários ou governamentais. As tarefas são atribuídas conforme as aptidões do adolescente, em jornada máxima de oito horas semanais, aos sábados, domingos e feriados ou em dias úteis, sem prejudicar a frequência à escola ou a jornada normal de trabalho.', '["Tarefas gratuitas de interesse geral.","Prazo máximo de seis meses.","Jornada máxima de oito horas semanais.","Sem prejudicar escola ou trabalho."]'::jsonb, '["Prazo máximo de seis meses e oito horas semanais."]'::jsonb, 'O adolescente trabalha oito horas semanais em uma escola pública, aos sábados.', '["Assertiva que fixa em doze meses o prazo da prestação de serviços erra: são seis meses."]'::jsonb, '[]'::jsonb, '["Art. 112"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-117' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6c6e54102ccf714505d6c0a1d63c1c3fa9563f6bf11a4e6b69f6a6b5d2d85a99'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A liberdade assistida é adotada sempre que se afigurar a medida mais adequada para acompanhar, auxiliar e orientar o adolescente. A autoridade designa pessoa capacitada para acompanhar o caso. A medida é fixada pelo prazo mínimo de seis meses, podendo a qualquer tempo ser prorrogada, revogada ou substituída, ouvidos o orientador, o Ministério Público e o defensor.', '["Acompanhamento, auxílio e orientação.","Orientador designado.","Prazo mínimo de seis meses.","Prorrogação, revogação ou substituição."]'::jsonb, '["Prazo MÍNIMO de seis meses (não há máximo fixo)."]'::jsonb, 'O adolescente em liberdade assistida é acompanhado por um orientador por, no mínimo, seis meses.', '["Assertiva que fixa prazo máximo de seis meses para a liberdade assistida erra: seis meses é o prazo mínimo."]'::jsonb, '[{"termo":"Liberdade assistida","significado":"Medida em meio aberto com acompanhamento e orientação do adolescente."}]'::jsonb, '["Art. 119"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-118' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '78dc029d6d88c36e1935e3f8ffafdf70294979bd16f0b41a3bcf4a298cd6dbf9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ao orientador, com o apoio e a supervisão da autoridade competente, promover socialmente o adolescente e sua família, supervisionar a frequência e o aproveitamento escolar e promover a matrícula, diligenciar a profissionalização e a inserção no mercado de trabalho e apresentar relatório do caso.', '["Promoção social do adolescente e da família.","Supervisão da frequência escolar.","Profissionalização.","Relatório do caso."]'::jsonb, '["Encargos do ORIENTADOR."]'::jsonb, 'O orientador acompanha a matrícula e a frequência escolar do adolescente.', '["Assertiva que dispensa o relatório do orientador erra."]'::jsonb, '[]'::jsonb, '["Art. 118"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-119' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a1d9d95a67eb139df3f55bd860e73912b443c3cfae7444cdb6438331e8d02d16'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O regime de semiliberdade pode ser determinado desde o início ou como transição para o meio aberto, possibilitada a realização de atividades externas independentemente de autorização judicial. São obrigatórias a escolarização e a profissionalização, utilizando-se recursos da comunidade. A medida não comporta prazo determinado, aplicando-se, no que couber, as disposições relativas à internação.', '["Desde o início ou como transição.","Atividades externas sem autorização judicial.","Escolarização e profissionalização obrigatórias.","Sem prazo determinado."]'::jsonb, '["Atividades externas independem de autorização judicial.","Sem prazo determinado."]'::jsonb, 'O adolescente em semiliberdade estuda fora da unidade durante o dia.', '["Assertiva que exige autorização judicial para cada atividade externa da semiliberdade erra."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-120' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'dfa054240d9d17ccfb8b295241eaf31f4e0222b5b371e30b561d137933f096d8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A internação é medida privativa de liberdade, sujeita aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento. Permitem-se atividades externas a critério da equipe técnica, salvo determinação judicial em contrário. A medida não comporta prazo determinado, e sua manutenção é reavaliada, por decisão fundamentada, no máximo a cada seis meses. O período máximo de internação não excede três anos. Atingido esse limite, o adolescente é liberado, colocado em semiliberdade ou em liberdade assistida. A liberação é compulsória aos vinte e um anos de idade.', '["Brevidade, excepcionalidade e condição peculiar.","Sem prazo determinado, reavaliada a cada seis meses.","Máximo de três anos.","Liberação compulsória aos vinte e um anos."]'::jsonb, '["Reavaliação a cada seis meses, no máximo.","Máximo de TRÊS anos e liberação compulsória aos VINTE E UM.","É a medida socioeducativa mais grave."]'::jsonb, 'O adolescente internado é liberado compulsoriamente ao completar vinte e um anos.', '["Assertiva que fixa em cinco anos o período máximo da internação erra: são três anos."]'::jsonb, '[{"termo":"Internação","significado":"Medida socioeducativa privativa de liberdade, breve e excepcional."}]'::jsonb, '["Art. 122"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-121' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5d37bf464fce96772fdc87dd49839762d4c28473022dc670be42b045e02e57ce'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A internação só pode ser aplicada quando se tratar de ato infracional cometido mediante grave ameaça ou violência a pessoa, por reiteração no cometimento de outras infrações graves ou por descumprimento reiterado e injustificável da medida anteriormente imposta. Neste último caso, o prazo da internação não pode ser superior a três meses, devendo ser decretada após o devido processo legal. Em nenhuma hipótese será aplicada a internação havendo outra medida adequada.', '["Grave ameaça ou violência a pessoa.","Reiteração em infrações graves.","Descumprimento reiterado e injustificável, por até três meses.","Subsidiariedade: só se não houver outra medida adequada."]'::jsonb, '["Internação-sanção: prazo máximo de TRÊS MESES.","Só cabe internação se não houver outra medida adequada."]'::jsonb, 'O adolescente que descumpre reiteradamente a liberdade assistida pode ser internado por até três meses.', '["Assertiva que fixa em seis meses a internação por descumprimento reiterado erra: são três meses."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-122' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8359fa1258f10034e8565f9fd01eecad4444559d026f69ca8f4f6e12cbffa40e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A internação deve ser cumprida em entidade exclusiva para adolescentes, em local distinto do destinado ao abrigo, com rigorosa separação por idade, compleição física e gravidade da infração. Durante a internação, inclusive provisória, são obrigatórias atividades pedagógicas.', '["Entidade exclusiva para adolescentes.","Separação por idade, compleição física e gravidade.","Atividades pedagógicas obrigatórias."]'::jsonb, '["Atividades pedagógicas valem inclusive na internação provisória."]'::jsonb, 'O adolescente internado frequenta aulas na própria unidade.', '["Assertiva que permite internar adolescentes em presídios comuns erra."]'::jsonb, '[]'::jsonb, '["Art. 121"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-123' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e24ea32c8f5af0ed91de41b5258e2dc1e910c7b1cdaa116a8dbf57514a944b06'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São direitos do adolescente privado de liberdade, entre outros, entrevistar-se pessoalmente com o representante do Ministério Público, peticionar diretamente a qualquer autoridade, avistar-se reservadamente com seu defensor, ser informado de sua situação processual, ser tratado com respeito e dignidade, permanecer internado na mesma localidade ou na mais próxima do domicílio dos pais, receber visitas e corresponder-se com familiares e amigos, ter acesso aos objetos necessários à higiene e asseio pessoal, habitar alojamento em condições adequadas, receber escolarização e profissionalização, realizar atividades culturais, esportivas e de lazer, ter acesso aos meios de comunicação social, receber assistência religiosa e manter a posse de seus objetos pessoais.', '["Entrevista com o Ministério Público e petição direta.","Contato reservado com o defensor.","Internação perto do domicílio dos pais.","Escolarização, profissionalização, lazer e assistência religiosa."]'::jsonb, '["Rol exemplificativo (\"entre outros\").","Internação preferencialmente próxima à residência dos pais."]'::jsonb, 'O adolescente internado pode conversar reservadamente com seu defensor.', '["Assertiva que impede o adolescente internado de peticionar diretamente a autoridades erra."]'::jsonb, '[]'::jsonb, '["Art. 125"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-124' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8f56f1b734fd14580cc4388b6adb5db650772a00042c1e34e9dfd235732dfaa6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever do Estado zelar pela integridade física e mental dos internos, cabendo-lhe adotar as medidas adequadas de contenção e segurança.', '["Dever estatal de zelar pela integridade.","Medidas de contenção e segurança."]'::jsonb, '["Responsabilidade do Estado pela integridade do interno."]'::jsonb, 'O Estado responde por agressão ocorrida dentro da unidade de internação.', '["Assertiva que isenta o Estado do dever de zelar pela integridade dos internos erra."]'::jsonb, '[]'::jsonb, '["Art. 124"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-125' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2937beedad6c2c5e329364e3c8e8d2a30f2f07fab6bc163e2878ea77ce89978c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Antes de iniciado o procedimento judicial para apuração de ato infracional, o representante do Ministério Público pode conceder a remissão, como forma de exclusão do processo, considerando as circunstâncias e consequências do fato, o contexto social e a personalidade do adolescente. Iniciado o procedimento, a remissão concedida pela autoridade judiciária importa na suspensão ou extinção do processo.', '["Remissão pelo Ministério Público antes do processo.","Exclusão do processo.","Após iniciado, a remissão judicial suspende ou extingue o processo."]'::jsonb, '["Antes do processo: o MINISTÉRIO PÚBLICO concede.","Depois de iniciado: a autoridade JUDICIÁRIA concede."]'::jsonb, 'O promotor concede remissão a adolescente primário em ato de menor gravidade.', '["Assertiva que atribui ao juiz a remissão concedida antes do início do processo erra: é do Ministério Público."]'::jsonb, '[{"termo":"Remissão","significado":"Perdão ou exclusão do processo, com ou sem medida, concedida ao adolescente."}]'::jsonb, '["Art. 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-126' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4ab26e65226fd169389875d4da39df49022bcc3a76a2906775f7197c490565ca'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A remissão não implica necessariamente o reconhecimento ou comprovação da responsabilidade, nem prevalece para efeito de antecedentes, podendo incluir eventualmente a aplicação de qualquer das medidas previstas em lei, exceto a semiliberdade e a internação.', '["Não implica reconhecimento de responsabilidade.","Não gera antecedentes.","Pode incluir medidas, exceto semiliberdade e internação."]'::jsonb, '["Não pode incluir SEMILIBERDADE nem INTERNAÇÃO.","Não vale como antecedente."]'::jsonb, 'A remissão cumulada com liberdade assistida é possível, mas não com internação.', '["Assertiva que permite a remissão cumulada com internação erra."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-127' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f16ea5c2bbb817b7fb87562a7a8dd7ea3f6799e5071f155c485340797fff2528'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A medida aplicada por força da remissão pode ser revista judicialmente, a qualquer tempo, mediante pedido expresso do adolescente ou de seu representante legal, ou do Ministério Público.', '["Revisão judicial a qualquer tempo.","Legitimados: adolescente, representante legal e Ministério Público."]'::jsonb, '["Revisão a QUALQUER tempo."]'::jsonb, 'O representante legal pede a revisão da medida acordada na remissão.', '["Assertiva que torna definitiva a medida da remissão erra."]'::jsonb, '[]'::jsonb, '["Art. 127"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-128' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4ce644d6b2dcd4da88e344391ec20f0a241db5d38c25620f7a82b9e484e2ee46'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São medidas aplicáveis aos pais ou responsável o encaminhamento a serviços de proteção à família, a inclusão em programa de auxílio e tratamento a alcoólatras e toxicômanos, o tratamento psicológico ou psiquiátrico, os cursos de orientação, a obrigação de matricular o filho e acompanhar sua frequência escolar, a obrigação de encaminhar a criança a tratamento especializado, a advertência, a perda da guarda, a destituição da tutela e a suspensão ou destituição do poder familiar. Na aplicação das medidas de perda da guarda, destituição da tutela e suspensão ou destituição do poder familiar, observa-se o disposto nos arts. 23 e 24.', '["Medidas brandas: encaminhamento, tratamento, cursos, advertência.","Medidas graves: perda da guarda, destituição da tutela, suspensão ou destituição do poder familiar.","Observância dos arts. 23 e 24."]'::jsonb, '["As medidas mais graves exigem decisão judicial.","Gradação: das orientações à destituição."]'::jsonb, 'Os pais que não matriculam o filho são obrigados a matriculá-lo e acompanhá-lo.', '["Assertiva que permite ao Conselho Tutelar destituir o poder familiar erra: depende de decisão judicial."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-129' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2fb8fe6f7a70f036151039b0966437988907f8be34623d48eda4f204ffff1de9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Verificada a hipótese de maus-tratos, negligência, opressão ou abuso sexual impostos pelos pais ou responsável, a autoridade judiciária pode determinar, como medida cautelar, o afastamento do agressor da moradia comum. Da medida consta ainda a fixação provisória de alimentos de que necessitem a criança ou o adolescente dependentes do agressor.', '["Afastamento do agressor da moradia comum.","Alimentos provisórios fixados na mesma decisão."]'::jsonb, '["Afasta-se o AGRESSOR, não a criança.","Alimentos provisórios acompanham a medida."]'::jsonb, 'O juiz afasta o pai agressor da casa e fixa alimentos provisórios.', '["Assertiva que determina o afastamento da criança em vez do agressor erra."]'::jsonb, '[]'::jsonb, '["Art. 129"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-130' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0cb2e358d7be02004fc81a6e31d54a45638bb2511816c701a84a19eb9c2957fa'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Conselho Tutelar é órgão permanente e autônomo, não jurisdicional, encarregado pela sociedade de zelar pelo cumprimento dos direitos da criança e do adolescente.', '["Órgão permanente.","Autônomo.","Não jurisdicional."]'::jsonb, '["NÃO JURISDICIONAL: não julga, nem aplica penas.","Permanente e autônomo."]'::jsonb, 'O Conselho Tutelar atende a denúncia de maus-tratos, mas não decide o processo judicial.', '["Assertiva que atribui função jurisdicional ao Conselho Tutelar erra."]'::jsonb, '[{"termo":"Conselho Tutelar","significado":"Órgão permanente, autônomo e não jurisdicional de proteção dos direitos da infância."}]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-131' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '29344d9df9bfcb101346980216bd5651025a079a889a7f1330805056afd688d4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em cada Município e em cada Região Administrativa do Distrito Federal haverá, no mínimo, um Conselho Tutelar como órgão integrante da administração pública local, composto de cinco membros, escolhidos pela população local para mandato de quatro anos, permitida recondução por novos processos de escolha.', '["Ao menos um Conselho Tutelar por Município.","Cinco membros.","Mandato de quatro anos.","Recondução por novo processo de escolha."]'::jsonb, '["Cinco membros, mandato de quatro anos.","ATUALIZAÇÃO: o mandato foi ampliado de três para quatro anos por lei posterior.","A recondução exige NOVO processo de escolha."]'::jsonb, 'A população elege cinco conselheiros tutelares para um mandato de quatro anos.', '["Assertiva que fixa o mandato em três anos erra: são quatro anos."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-132' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '692e40d06e99d8a331bb3a5cd47400bfa41a9589539a7ba68faadde687e061a5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para a candidatura a membro do Conselho Tutelar são exigidos reconhecida idoneidade moral, idade superior a vinte e um anos e residência no município.', '["Idoneidade moral.","Idade superior a vinte e um anos.","Residência no município."]'::jsonb, '["Mais de vinte e um anos."]'::jsonb, 'O candidato de vinte e dois anos que reside no município pode concorrer.', '["Assertiva que exige apenas dezoito anos para ser conselheiro tutelar erra: é idade superior a vinte e um anos."]'::jsonb, '[]'::jsonb, '["Art. 132"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-133' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'add7c4a62b403fd9bc9b979fd3ac3fb97e37c51b829f90e35ddcf35ec07c4cd9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lei municipal ou distrital define o local, dia e horário de funcionamento do Conselho Tutelar e a remuneração dos conselheiros, que têm direito a cobertura previdenciária, férias anuais remuneradas acrescidas de um terço, licença-maternidade, licença-paternidade e gratificação natalina. A lei orçamentária prevê os recursos necessários ao funcionamento do Conselho e à remuneração dos membros.', '["Lei local define funcionamento e remuneração.","Direitos: previdência, férias com um terço, licenças e gratificação natalina.","Recursos previstos no orçamento."]'::jsonb, '["ATUALIZAÇÃO: a remuneração e os direitos sociais foram assegurados por lei posterior.","Conselheiro tutelar é remunerado, ao contrário do conselheiro de direitos."]'::jsonb, 'O conselheiro tutelar tem férias com acréscimo de um terço.', '["Assertiva que nega remuneração ao conselheiro tutelar erra."]'::jsonb, '[]'::jsonb, '["Art. 89"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-134' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ea587f6c9a4ec775c96ad37a1ef25cf9f6fbfa36405aa7a67906a708fd413063'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O exercício efetivo da função de conselheiro tutelar constitui serviço público relevante e estabelece presunção de idoneidade moral.', '["Serviço público relevante.","Presunção de idoneidade moral."]'::jsonb, '["Presunção de idoneidade moral para quem exerceu a função."]'::jsonb, 'O ex-conselheiro tem a presunção de idoneidade moral em novas candidaturas.', '["Assertiva que nega relevância pública ao exercício da função de conselheiro erra."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-135' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2c06d99c4471c86e2f9283c7cd879d735e9954316cfe8e7d66df602d7a1fb491'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São atribuições do Conselho Tutelar atender crianças e adolescentes nas hipóteses dos arts. 98 e 105, aplicando as medidas de proteção; atender e aconselhar os pais ou responsável, aplicando as medidas a eles destinadas; promover a execução de suas decisões, requisitando serviços públicos e representando à autoridade judiciária; encaminhar ao Ministério Público notícia de infração administrativa ou penal; encaminhar à autoridade judiciária os casos de sua competência; providenciar medidas estabelecidas pela autoridade judiciária; expedir notificações; requisitar certidões de nascimento e óbito; assessorar o Poder Executivo local na elaboração da proposta orçamentária; representar contra violações de rádio e televisão; e fiscalizar entidades de atendimento, entre outras.', '["Atender crianças, adolescentes e pais.","Aplicar medidas de proteção e medidas aos pais.","Requisitar serviços públicos.","Encaminhar ao Ministério Público e à autoridade judiciária.","Assessorar o orçamento local.","Fiscalizar entidades."]'::jsonb, '["O Conselho Tutelar NÃO aplica medidas socioeducativas.","Não pode destituir poder familiar nem afastar o agressor: são medidas judiciais.","ATUALIZAÇÃO: o rol foi ampliado por leis posteriores."]'::jsonb, 'O Conselho Tutelar requisita atendimento de saúde para a criança e acompanha os pais.', '["Assertiva que atribui ao Conselho Tutelar a aplicação de medida socioeducativa de internação erra."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-136' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b01d38edbfa0f10830829d12e6f3b00a3af21336c2b662736c7685777777aed4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As decisões do Conselho Tutelar só podem ser revistas pela autoridade judiciária a pedido de quem tenha legítimo interesse.', '["Revisão apenas pela autoridade judiciária.","Depende de pedido de quem tem legítimo interesse."]'::jsonb, '["O juiz não revê de ofício as decisões do Conselho."]'::jsonb, 'Os pais pedem ao juiz a revisão da decisão do Conselho Tutelar.', '["Assertiva que permite ao Ministério Público Eleitoral revisar decisões do Conselho erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-137' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4b8d8e061925b8c6be5b75a8c784729de8ac3d9c3226d343673ac5477bc6bc21'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplica-se ao Conselho Tutelar a regra de competência territorial do art. 147: domicílio dos pais ou responsável ou, à falta destes, o lugar onde se encontre a criança ou adolescente.', '["Competência pelo domicílio dos pais ou responsável.","Alternativa: lugar onde se encontra a criança."]'::jsonb, '["Mesma regra de competência do art. 147."]'::jsonb, 'O Conselho do bairro onde moram os pais atende o caso.', '["Assertiva que fixa a competência do Conselho pelo local do fato sempre erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-138' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7e9b0a955a3b1f5715f48faf98b719dada0365cd4cfb8e97c3045dac241355e9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo de escolha dos membros do Conselho Tutelar é estabelecido em lei municipal, realizado sob responsabilidade do Conselho Municipal dos Direitos da Criança e do Adolescente e fiscalizado pelo Ministério Público. Ocorre em data unificada em todo o território nacional, a cada quatro anos, no primeiro domingo do mês de outubro do ano subsequente ao da eleição presidencial. A posse dos conselheiros ocorre no dia dez de janeiro do ano seguinte.', '["Lei municipal e Conselho Municipal dos Direitos.","Fiscalização pelo Ministério Público.","Data unificada: primeiro domingo de outubro do ano seguinte à eleição presidencial.","Posse em dez de janeiro."]'::jsonb, '["Escolha em data UNIFICADA nacional, a cada quatro anos.","Primeiro domingo de outubro do ano seguinte à eleição presidencial."]'::jsonb, 'Todos os municípios escolhem conselheiros no mesmo dia.', '["Assertiva que deixa a data da escolha a critério de cada município erra: é unificada nacionalmente."]'::jsonb, '[]'::jsonb, '["Art. 132"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-139' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1e343ac6e0f0c19afabfeddf98c86be424ea028187c5c18307ddb0cb42507655'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São impedidos de servir no mesmo Conselho marido e mulher, ascendentes e descendentes, sogro e genro ou nora, irmãos, cunhados durante o cunhadio, tio e sobrinho, padrasto ou madrasta e enteado. O impedimento se estende em relação à autoridade judiciária e ao representante do Ministério Público com atuação na Justiça da Infância e da Juventude na comarca.', '["Impedimento entre parentes no mesmo Conselho.","Extensão ao juiz e ao promotor da Infância da comarca."]'::jsonb, '["O impedimento alcança o juiz e o promotor da Infância."]'::jsonb, 'Dois irmãos não podem ser conselheiros do mesmo Conselho Tutelar.', '["Assertiva que permite pai e filho no mesmo Conselho erra."]'::jsonb, '[]'::jsonb, '["Art. 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-140' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '86d2a3d05fa8e70efd53fef6b74c8c17c789bf501ee6396902aa60b99abeafa9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É garantido o acesso de toda criança ou adolescente à Defensoria Pública, ao Ministério Público e ao Poder Judiciário, por qualquer de seus órgãos. A assistência judiciária gratuita é prestada aos que dela necessitarem, por defensor público ou advogado nomeado, e as ações da Justiça da Infância e da Juventude são isentas de custas e emolumentos, ressalvada a litigância de má-fé.', '["Acesso à Defensoria, ao Ministério Público e ao Judiciário.","Assistência judiciária gratuita.","Isenção de custas, salvo má-fé."]'::jsonb, '["Isenção de custas e emolumentos, ressalvada a litigância de má-fé."]'::jsonb, 'A mãe ajuíza ação sem pagar custas na Vara da Infância.', '["Assertiva que cobra custas das ações da Justiça da Infância erra."]'::jsonb, '[]'::jsonb, '["Art. 111"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-141' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '639f59da1a153faf1d51a0f202306a77ebc2bba900bb8ada52f8f4146ef2c627'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os menores de dezesseis anos são representados e os maiores de dezesseis e menores de vinte e um anos são assistidos por seus pais, tutores ou curadores, na forma da lei civil ou processual. A autoridade judiciária nomeia curador especial à criança ou adolescente sempre que seus interesses colidirem com os dos pais ou responsável, ou quando carecer de representação ou assistência legal, ainda que eventual.', '["Representação até dezesseis anos e assistência depois.","Curador especial em caso de colisão de interesses."]'::jsonb, '["Curador especial quando houver COLISÃO de interesses com os pais."]'::jsonb, 'O juiz nomeia curador especial à criança cujos pais são os acusados.', '["Assertiva que dispensa o curador especial quando os interesses da criança colidirem com os dos pais erra."]'::jsonb, '[]'::jsonb, '["Art. 148"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-142' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '08c08edd56f2584b123e709ccf4156aa1e1e30169873a40cafcb0f8521949964'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
