insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É vedada a divulgação de atos judiciais, policiais e administrativos relativos a crianças e adolescentes a quem se atribua ato infracional. Qualquer notícia sobre o fato não pode identificar a criança ou adolescente, sendo proibidas fotografia, referência a nome, apelido, filiação, parentesco, residência e, inclusive, iniciais do nome e sobrenome.', '["Vedada a divulgação de atos sobre ato infracional.","Proibida a identificação, inclusive por iniciais."]'::jsonb, '["Vedadas até as INICIAIS do nome e sobrenome."]'::jsonb, 'A reportagem não pode divulgar o nome nem as iniciais do adolescente.', '["Assertiva que permite divulgar as iniciais do adolescente erra."]'::jsonb, '[]'::jsonb, '["Art. 247"]'::jsonb, 'under_review', 'claude'
