insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A expedição de cópia ou certidão dos atos de que trata o artigo anterior só é deferida pela autoridade judiciária competente, se demonstrado o interesse e justificada a finalidade.', '["Cópia ou certidão só com autorização judicial.","Exige interesse demonstrado e finalidade justificada."]'::jsonb, '["Depende de decisão da autoridade judiciária."]'::jsonb, 'A certidão do processo só é fornecida mediante autorização do juiz.', '["Assertiva que permite ao escrivão fornecer certidão a qualquer interessado erra."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
