insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade a que se refere o Estatuto é o Juiz da Infância e da Juventude, ou o juiz que exerce essa função, na forma da lei de organização judiciária local.', '["Juiz da Infância e da Juventude.","Ou o juiz que exerce a função, conforme a organização local."]'::jsonb, '["Em comarcas sem vara especializada, outro juiz exerce a função."]'::jsonb, 'Na comarca pequena, o juiz único atua como Juiz da Infância.', '["Assertiva que exige vara exclusiva em todas as comarcas erra."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-146' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0137b3cf093949d18b7fd3b3de1c2f0b3115afd76631f1b4a5d869b570614c88'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
