insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência é determinada pelo domicílio dos pais ou responsável ou, à falta destes, pelo lugar onde se encontre a criança ou adolescente. Nos atos infracionais, é competente a autoridade do lugar da ação ou omissão, observadas as regras de conexão, continência e prevenção. A execução das medidas pode ser delegada à autoridade da residência dos pais ou do local da entidade. As ações de adoção e as de crianças em acolhimento observam regras próprias.', '["Domicílio dos pais ou responsável.","À falta, lugar onde está a criança.","Ato infracional: lugar da ação ou omissão.","Execução delegável."]'::jsonb, '["Ato infracional: competência do lugar da AÇÃO ou OMISSÃO.","A execução pode ser delegada."]'::jsonb, 'O ato infracional é julgado no local onde ocorreu.', '["Assertiva que fixa o domicílio do adolescente como competência no ato infracional erra: é o lugar da ação ou omissão."]'::jsonb, '[]'::jsonb, '["Art. 148"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-147' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1d447e2187a38668b3e82fa4297b68ebf929225fda43103a6e9af1164f841d81'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Justiça da Infância e da Juventude é competente para conhecer de representações do Ministério Público para apuração de ato infracional, conceder a remissão como forma de suspensão ou extinção do processo, conhecer de pedidos de adoção e seus incidentes, conhecer de ações civis fundadas em interesses individuais, difusos ou coletivos afetos à criança e ao adolescente, ações decorrentes de irregularidades em entidades de atendimento, aplicar penalidades administrativas por infrações às normas de proteção e conhecer de casos encaminhados pelo Conselho Tutelar. Em relação a crianças e adolescentes, também conhece de pedidos de guarda, tutela, destituição, suprimento de consentimento para casamento e alvarás.', '["Apuração de ato infracional.","Remissão judicial.","Adoção e incidentes.","Ações civis de interesse da infância.","Penalidades administrativas.","Guarda, tutela, destituição e outros pedidos."]'::jsonb, '["Alimentos e guarda em disputa entre pais ficam, em regra, na vara de família, salvo situação de risco.","O rol é amplo; vale conferir o art. 148 para as hipóteses em que a vara da infância é competente."]'::jsonb, 'A Vara da Infância processa o pedido de adoção.', '["Assertiva que atribui à Vara da Infância toda disputa de guarda entre pais separados erra."]'::jsonb, '[]'::jsonb, '["Art. 147"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-148' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b9d6897e080ab3f1034f42a2ad9549eb5ae2e7eb95c595763caef7e13b244a33'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à autoridade judiciária disciplinar, por portaria, ou autorizar, mediante alvará, a entrada e permanência de criança ou adolescente, desacompanhado dos pais, em estádios, bailes, boates, casas de diversões eletrônicas e estúdios; e a participação de criança e adolescente em espetáculos públicos e seus ensaios e em certames de beleza. A portaria deve ser fundamentada, caso a caso, vedadas as determinações de caráter geral.', '["Portaria ou alvará para entrada em locais de diversão.","Participação em espetáculos e certames.","Fundamentação caso a caso."]'::jsonb, '["Vedadas as determinações de caráter GERAL: a decisão é caso a caso."]'::jsonb, 'O juiz autoriza, por alvará, a participação de uma criança em peça teatral.', '["Assertiva que permite ao juiz proibir, de modo geral e abstrato, a entrada de adolescentes em eventos erra: é caso a caso."]'::jsonb, '[{"termo":"Alvará judicial","significado":"Autorização individual concedida pelo juiz para um caso específico."}]'::jsonb, '["Art. 258"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-149' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a4a6e37adbceee9d3f3f27fe3c027cb95da936ce42af9fbd25925a744878a2a9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
