insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cabe ao Poder Judiciário, na elaboração de sua proposta orçamentária, prever recursos para a manutenção de equipe interprofissional destinada a assessorar a Justiça da Infância e da Juventude.', '["Previsão orçamentária pelo Poder Judiciário.","Equipe interprofissional de assessoria."]'::jsonb, '["O encargo é do PODER JUDICIÁRIO."]'::jsonb, 'O tribunal reserva verba para contratar psicólogos e assistentes sociais.', '["Assertiva que atribui ao Executivo o custeio da equipe interprofissional da Vara erra."]'::jsonb, '[]'::jsonb, '["Art. 151"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-150' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'be348f6967932aa3a0b3550a25da0995025a5fa25ca727fd9fbbc7ee6e229865'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à equipe interprofissional fornecer subsídios por escrito, mediante laudos, ou verbalmente, na audiência, e desenvolver trabalhos de aconselhamento, orientação, encaminhamento e prevenção, sob a imediata subordinação à autoridade judiciária, assegurada a livre manifestação do ponto de vista técnico. Na ausência ou insuficiência de servidores públicos integrantes do Poder Judiciário responsáveis pela realização dos estudos psicossociais, a autoridade judiciária poderá proceder à nomeação de perito.', '["Laudos e manifestação oral.","Aconselhamento, orientação e prevenção.","Subordinação ao juiz com liberdade técnica.","Nomeação de perito se faltarem servidores."]'::jsonb, '["Liberdade de manifestação do ponto de vista TÉCNICO.","ATUALIZAÇÃO: parágrafo único incluído por lei posterior."]'::jsonb, 'A psicóloga da vara apresenta laudo ao juiz e defende seu ponto de vista técnico.', '["Assertiva que sujeita o parecer técnico à opinião do juiz erra: há livre manifestação técnica."]'::jsonb, '[]'::jsonb, '["Art. 150"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-151' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '104bfb03225ab6fe366193c1abcf687502a89523b9dc87b4b14d401da62d2ae9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
