on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aos procedimentos do Estatuto aplicam-se subsidiariamente as normas gerais da legislação processual pertinente. Há prioridade absoluta na tramitação dos processos e na execução de atos e diligências judiciais, sob pena de responsabilidade. Os prazos do Estatuto são contados em dias corridos, excluído o dia do começo e incluído o do vencimento, vedado o prazo em dobro para a Fazenda Pública e o Ministério Público.', '["Aplicação subsidiária da legislação processual.","Prioridade absoluta na tramitação.","Prazos em dias corridos.","Sem prazo em dobro para Fazenda Pública e Ministério Público."]'::jsonb, '["ATUALIZAÇÃO: prazos em dias corridos, sem prazo em dobro, vieram de lei posterior.","Prioridade ABSOLUTA, sob pena de responsabilidade."]'::jsonb, 'O prazo do Ministério Público não é contado em dobro nos processos do Estatuto.', '["Assertiva que prevê prazo em dobro para o Ministério Público nos procedimentos do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-152' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '82c58f2e3fcca31c5bd6c643bfe362d687ae084b6e26e7eda7c922020bb58646'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a medida judicial a ser adotada não corresponder a procedimento previsto no Estatuto ou em outra lei, a autoridade judiciária pode investigar os fatos e ordenar de ofício as providências necessárias, ouvido o Ministério Público. Isso não se aplica ao afastamento da criança ou do adolescente de sua família de origem nem a outros procedimentos necessariamente contenciosos.', '["Poder de investigação e providências de ofício, ouvido o Ministério Público.","Exceção: afastamento da família de origem e procedimentos contenciosos."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único limitou a atuação de ofício.","Não vale para afastar a criança da família de origem."]'::jsonb, 'O juiz pode determinar de ofício providências em situação sem rito próprio, exceto afastar a criança da família.', '["Assertiva que permite ao juiz afastar a criança da família de origem de ofício erra."]'::jsonb, '[]'::jsonb, '["Art. 152"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-153' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9136ad2e4e1fee44732a2f9aa13c3f6094166b2a17c0a316b3634e4e19d0dfa1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
