insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplica-se às multas o disposto no art. 214, ou seja, o produto das multas reverte ao fundo municipal dos direitos da criança e do adolescente.', '["Regime das multas segue o art. 214."]'::jsonb, '["Destino das multas: fundo municipal."]'::jsonb, 'A multa aplicada a um estabelecimento vai para o fundo dos direitos da criança.', '["Assertiva que destina as multas ao Tesouro Nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
