insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A petição inicial indica a autoridade judiciária a que é dirigida; o nome, estado civil, profissão e residência do requerente e do requerido, dispensada a qualificação quando o pedido for formulado pelo Ministério Público; a exposição sumária do fato e o pedido; e as provas a produzir, com o rol de testemunhas e documentos.', '["Autoridade, qualificação, fato e pedido, provas.","Dispensa de qualificação quando o autor é o Ministério Público."]'::jsonb, '["Rol de testemunhas e documentos já na inicial."]'::jsonb, 'A inicial indica desde logo as testemunhas e documentos.', '["Assertiva que dispensa o rol de testemunhas na petição inicial erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
