insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Havendo motivo grave, a autoridade judiciária, ouvido o Ministério Público, pode decretar a suspensão do poder familiar, liminar ou incidentalmente, até o julgamento definitivo da causa, ficando a criança confiada a pessoa idônea mediante termo de responsabilidade. Recebida a inicial, o juiz determina, independentemente de requerimento, a realização de estudo social ou perícia por equipe interprofissional, e, se a criança ainda não tiver sido ouvida, a oitiva.', '["Suspensão liminar do poder familiar por motivo grave.","Criança confiada a pessoa idônea.","Estudo social ou perícia determinados de ofício."]'::jsonb, '["Exige MOTIVO GRAVE e oitiva do Ministério Público."]'::jsonb, 'O juiz suspende liminarmente o poder familiar e confia a criança a um parente idôneo.', '["Assertiva que dispensa a oitiva do Ministério Público na suspensão liminar erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-157' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b9d0ee0fff59055620365345a3854b1fdd9a6121668f90761d51489a8c7bf4bd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
