insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O requerido é citado para, no prazo de dez dias, oferecer resposta escrita, indicando as provas e oferecendo o rol de testemunhas e documentos. A citação é pessoal, salvo se esgotados todos os meios, e o requerido privado de liberdade deve ser citado pessoalmente. Quando o oficial de justiça procurar duas vezes o citando sem encontrá-lo, deverá comunicar o fato ao juiz, e a citação por edital observa regras próprias.', '["Prazo de dez dias para resposta.","Citação pessoal, inclusive do preso.","Citação por edital em último caso."]'::jsonb, '["Prazo de dez dias.","Requerido preso: citação pessoal."]'::jsonb, 'O pai preso é citado pessoalmente para responder à ação.', '["Assertiva que fixa em quinze dias o prazo de resposta erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-158' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'de6149746f1aabc4c2999ef07246bff3252eb44a8148ee9024fb33e96576a7c4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
