on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o requerido não tiver possibilidade de constituir advogado sem prejuízo do próprio sustento e de sua família, pode requerer em cartório a nomeação de dativo, a quem incumbe apresentar a resposta, contando-se o prazo a partir da intimação do despacho de nomeação. Se o requerido estiver privado de liberdade, o oficial de justiça pergunta, no momento da citação, se deseja que lhe seja nomeado defensor.', '["Advogado dativo para quem não pode custear defensor.","Prazo conta da intimação da nomeação.","Pergunta ao requerido preso no ato da citação."]'::jsonb, '["O oficial de justiça pergunta ao preso se deseja defensor."]'::jsonb, 'O pai sem recursos pede um advogado dativo em cartório.', '["Assertiva que dispensa a pergunta ao requerido preso sobre a nomeação de defensor erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-159' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3689a982cafc42b8dc765ad9272d8bf2ea32c55fc9779a3fffe13e4bc622fbb6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sendo necessário, a autoridade judiciária requisita de qualquer repartição ou órgão público a apresentação de documento que interesse à causa, de ofício ou a requerimento das partes ou do Ministério Público.', '["Requisição de documentos a órgãos públicos.","De ofício ou a requerimento."]'::jsonb, '["Possível de ofício."]'::jsonb, 'O juiz requisita ao hospital o prontuário da criança.', '["Assertiva que depende de requerimento das partes para requisitar documentos erra: pode ser de ofício."]'::jsonb, '[]'::jsonb, '["Art. 157"]'::jsonb, 'under_review', 'claude'
