insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentada a resposta, a autoridade judiciária dá vista dos autos ao Ministério Público por cinco dias, salvo quando este for o requerente, designando desde logo audiência de instrução e julgamento. Na audiência, presentes as partes e o Ministério Público, são ouvidas as testemunhas, colhendo-se oralmente o parecer técnico, salvo se apresentado por escrito, e manifestam-se sucessivamente o requerente, o requerido e o Ministério Público. A decisão é proferida na audiência ou no prazo legal.', '["Vista ao Ministério Público por cinco dias.","Audiência de instrução e julgamento.","Oitiva de testemunhas e parecer técnico.","Manifestação sucessiva das partes."]'::jsonb, '["Cinco dias para o Ministério Público."]'::jsonb, 'Após a contestação, o juiz marca a audiência de instrução.', '["Assertiva que dispensa a audiência de instrução na perda do poder familiar contestada erra."]'::jsonb, '[]'::jsonb, '["Art. 161"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-162' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'fcab709374902908aea88884e449d2f4159e9627e00a4194fa76e87c8ea619f9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo máximo para conclusão do procedimento de perda ou suspensão do poder familiar é de cento e vinte dias. No caso de notória inviabilidade de manutenção do poder familiar, o juiz dirige esforços para preparar a criança ou o adolescente com vistas à colocação em família substituta. A sentença que decretar a perda ou a suspensão é averbada à margem do registro de nascimento.', '["Prazo máximo de cento e vinte dias.","Preparação para família substituta se inviável a manutenção.","Averbação da sentença no registro de nascimento."]'::jsonb, '["ATUALIZAÇÃO: prazo de cento e vinte dias fixado pela Lei de Adoção.","Sentença averbada à margem do registro."]'::jsonb, 'A ação de destituição deve ser concluída em até cento e vinte dias.', '["Assertiva que fixa em noventa dias o prazo máximo do procedimento erra: são cento e vinte dias."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-163' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1089b77154bd898412d883194b64b0f5f1af650d26659a0627ae368fecc5b16e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na destituição da tutela, observa-se o procedimento para a remoção de tutor previsto na lei processual civil e, no que couber, o disposto na seção anterior sobre a perda e a suspensão do poder familiar.', '["Procedimento de remoção de tutor da lei processual civil.","Aplicação subsidiária das regras anteriores."]'::jsonb, '["Remissão à lei processual civil."]'::jsonb, 'O tutor negligente é removido pelo rito da lei processual civil.', '["Assertiva que cria rito próprio e totalmente distinto para a destituição da tutela erra."]'::jsonb, '[]'::jsonb, '["Art. 38"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-164' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b4bc4b31ff82e836d4de8bdac289864efc4f0fc9e30324d634ea3ad377abe811'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
