insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade judiciária, de ofício ou a requerimento das partes ou do Ministério Público, determina a realização de estudo social ou, se possível, perícia por equipe interprofissional, decidindo sobre a concessão de guarda provisória e, na adoção, sobre o estágio de convivência. Deferidas a guarda provisória ou o estágio, a criança é entregue ao interessado mediante termo de responsabilidade.', '["Estudo social ou perícia por equipe interprofissional.","Guarda provisória e estágio de convivência.","Entrega mediante termo de responsabilidade."]'::jsonb, '["Estudo social realizado até de ofício."]'::jsonb, 'O juiz determina estudo social e concede guarda provisória aos candidatos.', '["Assertiva que dispensa o termo de responsabilidade na entrega da criança erra."]'::jsonb, '[]'::jsonb, '["Art. 46"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-167' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '45c193acc00bf209ef19bdc8fdb5e371f89d9bc6a231564364d991677b250702'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
