insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentado o relatório social ou o laudo pericial, e ouvida, sempre que possível, a criança ou o adolescente, dá-se vista dos autos ao Ministério Público pelo prazo de cinco dias, decidindo a autoridade judiciária em igual prazo.', '["Vista ao Ministério Público por cinco dias.","Decisão em igual prazo.","Oitiva da criança sempre que possível."]'::jsonb, '["Cinco dias para o MP e cinco para a decisão."]'::jsonb, 'Com o laudo pronto, o promotor tem cinco dias para opinar.', '["Assertiva que fixa em três dias a vista ao Ministério Público erra: são cinco dias."]'::jsonb, '[]'::jsonb, '["Art. 167"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-168' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cb15476a74c28afbdac8ff366eeba47c087c0e5ce4d6ac13e4cb98fd73ac5c39'
