insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a destituição da tutela, a perda ou a suspensão do poder familiar for pressuposto lógico da colocação em família substituta, observa-se o procedimento contraditório previsto nas seções anteriores. A perda ou a modificação da guarda pode ser decretada nos mesmos autos do procedimento.', '["Procedimento contraditório quando houver pressuposto lógico.","Perda ou modificação da guarda nos mesmos autos."]'::jsonb, '["Cumulação de pedidos nos mesmos autos."]'::jsonb, 'A destituição do poder familiar e a colocação em família substituta tramitam juntas.', '["Assertiva que exige processos separados para destituição e colocação em família substituta erra."]'::jsonb, '[]'::jsonb, '["Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-169' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '871b8c928a4de728848458502ec9dac67629496bfdb2cd13ffd66ad980ed30fd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
