select u.id, u.content_sha256, 'O adolescente apreendido por força de ordem judicial é desde logo encaminhado à autoridade judiciária.', '["Apreensão por ordem judicial: encaminhamento ao juiz."]'::jsonb, '["Diferente do flagrante, que vai à autoridade policial."]'::jsonb, 'O adolescente com mandado de busca e apreensão é levado ao juiz.', '["Assertiva que encaminha à polícia o adolescente apreendido por ordem judicial erra."]'::jsonb, '[]'::jsonb, '["Art. 172"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-171' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b7ae853fb3de98e960f331796bcc94a7cc258ab9fc6c1474c7789cd48eda39eb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
