insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O adolescente apreendido em flagrante de ato infracional é desde logo encaminhado à autoridade policial competente. Havendo repartição policial especializada e ato infracional praticado em coautoria com maior, prevalece a atribuição da repartição especializada, que, após as providências necessárias, encaminha o adulto à repartição própria.', '["Flagrante: encaminhamento à autoridade policial.","Coautoria com maior: prevalece a repartição especializada."]'::jsonb, '["Coautoria com adulto: delegacia especializada do adolescente tem a atribuição."]'::jsonb, 'Adolescente e adulto presos juntos são levados à delegacia especializada.', '["Assertiva que manda levar o adolescente à delegacia comum quando há coautor adulto erra."]'::jsonb, '[]'::jsonb, '["Art. 173"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-172' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c0405c270df997bdd69d91c5e01417e6645fb6d695cbfee0778615ab48a79c8a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No flagrante de ato infracional cometido com violência ou grave ameaça a pessoa, a autoridade policial deve lavrar auto de apreensão, ouvidos as testemunhas e o adolescente, apreender o produto e os instrumentos da infração e requisitar os exames ou perícias necessários. Nas demais hipóteses de flagrante, a lavratura do auto pode ser substituída por boletim de ocorrência circunstanciado.', '["Auto de apreensão nos atos violentos.","Apreensão do produto e dos instrumentos.","Boletim de ocorrência circunstanciado nos demais casos."]'::jsonb, '["Auto de apreensão só nos atos com VIOLÊNCIA ou GRAVE AMEAÇA; nos demais, basta o boletim."]'::jsonb, 'No roubo, a polícia lavra auto de apreensão; no furto, basta o boletim.', '["Assertiva que exige auto de apreensão em qualquer flagrante de ato infracional erra."]'::jsonb, '[]'::jsonb, '["Art. 106"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-173' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '747e13a8d0196c867f2a6514d14f6d6bde12c256f1fe095d905055083d40de0b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comparecendo qualquer dos pais ou o responsável, o adolescente é prontamente liberado pela autoridade policial, sob termo de compromisso e responsabilidade de sua apresentação ao Ministério Público no mesmo dia ou, sendo impossível, no primeiro dia útil imediato, exceto quando, pela gravidade do ato infracional e sua repercussão social, deva permanecer sob internação para garantia de sua segurança pessoal ou manutenção da ordem pública.', '["Liberação aos pais sob termo de compromisso.","Apresentação ao Ministério Público no mesmo dia ou no primeiro dia útil.","Exceção: gravidade e repercussão social."]'::jsonb, '["Apresentação ao Ministério Público no MESMO DIA ou no primeiro dia útil."]'::jsonb, 'A mãe retira o adolescente na delegacia e assina o termo de compromisso.', '["Assertiva que impede a liberação do adolescente aos pais em qualquer hipótese erra."]'::jsonb, '[]'::jsonb, '["Art. 175"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-174' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7e5b35ed54f6f4de3646a7d6fa4f245a96a14b8d1e4612f9160e0adf1953aa5b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de não liberação, a autoridade policial encaminha desde logo o adolescente ao Ministério Público, com cópia do auto de apreensão ou boletim de ocorrência. Sendo impossível a apresentação imediata, encaminha-o à entidade de atendimento, que o apresenta ao Ministério Público no prazo de vinte e quatro horas. Onde não houver entidade de atendimento, a apresentação é feita pela autoridade policial, e, na falta de repartição especializada, o adolescente aguarda em dependência separada de adultos.', '["Encaminhamento ao Ministério Público com cópia do auto.","Entidade de atendimento apresenta em vinte e quatro horas.","Dependência separada de adultos."]'::jsonb, '["Apresentação em até vinte e quatro horas.","Nunca junto a adultos."]'::jsonb, 'Sem delegacia especializada, o adolescente aguarda separado dos adultos.', '["Assertiva que fixa em quarenta e oito horas a apresentação ao Ministério Público erra: são vinte e quatro horas."]'::jsonb, '[]'::jsonb, '["Art. 174"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-175' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'aa114b5655993ffbf31346beab4d5874bd8bdd7f81fa1ec740a7aaed94124b4c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
