insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, afastada a hipótese de flagrante, houver indícios de participação de adolescente na prática de ato infracional, a autoridade policial encaminha ao Ministério Público o relatório das investigações e os demais documentos.', '["Fora do flagrante: relatório e documentos ao Ministério Público."]'::jsonb, '["Não se trata de inquérito com indiciamento."]'::jsonb, 'A polícia investiga e envia o relatório ao promotor.', '["Assertiva que obriga a polícia a instaurar inquérito policial contra o adolescente erra."]'::jsonb, '[]'::jsonb, '["Art. 179"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-177' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '929c57ccf951754d8a0c811e24638799799e43c40af3c7a1b92e4529e44034c7'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
