insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O adolescente a quem se atribua autoria de ato infracional não pode ser conduzido ou transportado em compartimento fechado de veículo policial, em condições atentatórias à sua dignidade ou que impliquem risco à sua integridade física ou mental, sob pena de responsabilidade.', '["Vedado o compartimento fechado em condições indignas.","Responsabilidade do agente."]'::jsonb, '["Proteção da dignidade na condução."]'::jsonb, 'O adolescente não pode ser levado no porta-malas da viatura.', '["Assertiva que permite o transporte em compartimento fechado sem restrições erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-178' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '50906fe006ae614c2ffd6a192b3ab458b696eb1d7a7dcc11d46953b99cc53ca6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentado o adolescente, o representante do Ministério Público, no mesmo dia e à vista do auto de apreensão, boletim ou relatório policial, com informação sobre os antecedentes do adolescente, procede imediata e informalmente à sua oitiva e, se possível, à de seus pais, da vítima e das testemunhas. Em caso de não apresentação, o promotor notifica os pais para apresentá-lo, sob pena de condução coercitiva.', '["Oitiva informal pelo Ministério Público no mesmo dia.","Oitiva dos pais, vítima e testemunhas, se possível.","Notificação dos pais em caso de não apresentação."]'::jsonb, '["A oitiva é INFORMAL e IMEDIATA."]'::jsonb, 'O promotor ouve informalmente o adolescente no dia da apresentação.', '["Assertiva que torna formal e posterior a oitiva do adolescente pelo Ministério Público erra."]'::jsonb, '[{"termo":"Oitiva informal","significado":"Audiência do adolescente pelo Ministério Público sem formalidades processuais."}]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-179' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '815e7b8e5bea0bd6da3689c3b63259ba3b90e7002a4a8eab59febdf4b7144222'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Adotadas as providências do artigo anterior, o representante do Ministério Público pode promover o arquivamento dos autos, conceder a remissão ou representar à autoridade judiciária para aplicação de medida socioeducativa.', '["Arquivar.","Conceder remissão.","Representar para medida socioeducativa."]'::jsonb, '["Três caminhos para o promotor."]'::jsonb, 'O promotor concede remissão ao adolescente em ato de menor gravidade.', '["Assertiva que obriga o promotor a sempre representar erra: pode arquivar ou conceder remissão."]'::jsonb, '[]'::jsonb, '["Art. 181"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-180' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'be8c9bed988068e13a23fea741ade177446d543b3dc12d1b07f4f49156fa9ebf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Promovido o arquivamento ou concedida a remissão pelo Ministério Público, mediante termo fundamentado com o resumo dos fatos, os autos são conclusos à autoridade judiciária para homologação. Homologado, o juiz determina o cumprimento da medida. Se discordar, o juiz remete os autos ao Procurador-Geral de Justiça, mediante despacho fundamentado, e este oferece representação, designa outro membro para fazê-lo ou ratifica o arquivamento ou a remissão, que então vincula o juiz.', '["Homologação judicial do arquivamento ou da remissão.","Discordância do juiz: remessa ao Procurador-Geral de Justiça.","Decisão final do Procurador-Geral vincula o juiz."]'::jsonb, '["Quem decide a divergência é o PROCURADOR-GERAL DE JUSTIÇA."]'::jsonb, 'O juiz discorda do arquivamento e remete ao Procurador-Geral.', '["Assertiva que permite ao juiz impor a representação ao promotor erra."]'::jsonb, '[]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-181' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd7436571a9913894afb2c65a663071a17f043c2b21a27b34c2be7f94305f7ad4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o Ministério Público não promover o arquivamento nem conceder a remissão, oferece representação à autoridade judiciária, propondo a instauração de procedimento para aplicação da medida socioeducativa mais adequada. A representação é oferecida por petição, com breve resumo dos fatos, classificação do ato infracional e rol de testemunhas, podendo ser deduzida oralmente em sessão diária instalada pela autoridade judiciária. A representação independe de prova pré-constituída da autoria e materialidade.', '["Representação como ato de acusação do Ministério Público.","Petição com resumo dos fatos e classificação.","Possibilidade de representação oral.","Independe de prova pré-constituída."]'::jsonb, '["Representação INDEPENDE de prova pré-constituída."]'::jsonb, 'O promotor oferece a representação por petição para instaurar o procedimento.', '["Assertiva que exige prova pré-constituída para oferecer a representação erra."]'::jsonb, '[{"termo":"Representação","significado":"Peça do Ministério Público que dá início ao procedimento de apuração de ato infracional."}]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-182' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b5b1c3ef582374a66466595d5398c6142c9441e09220968bcb1be70101377487'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo máximo e improrrogável para a conclusão do procedimento, estando o adolescente internado provisoriamente, é de quarenta e cinco dias.', '["Prazo máximo de quarenta e cinco dias.","Improrrogável."]'::jsonb, '["Improrrogável: quarenta e cinco dias.","Coincide com o prazo da internação provisória."]'::jsonb, 'O processo contra o adolescente internado deve terminar em quarenta e cinco dias.', '["Assertiva que permite prorrogar o prazo de quarenta e cinco dias erra: é improrrogável."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-183' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8821e86b06b11078a090d39997dacd1a64d93efe26fb4745a083e48b9b876e27'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Oferecida a representação, a autoridade judiciária designa audiência de apresentação do adolescente, decidindo desde logo sobre a decretação ou manutenção da internação, observado o art. 108. O adolescente e seus pais ou responsável são cientificados do teor da representação e notificados a comparecer, acompanhados de advogado. Se os pais não forem localizados, o juiz nomeia curador especial, e, não sendo localizado o adolescente, expede mandado de busca e apreensão. Estando o adolescente internado, será requisitada a sua apresentação.', '["Audiência de apresentação.","Decisão sobre a internação provisória.","Presença de advogado.","Curador especial se os pais não forem localizados."]'::jsonb, '["Defesa técnica por advogado na audiência."]'::jsonb, 'O juiz designa a audiência de apresentação e decide sobre a internação.', '["Assertiva que dispensa advogado na audiência de apresentação erra."]'::jsonb, '[]'::jsonb, '["Art. 108"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-184' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0fad6285f8595d10ae3db5cc94c035c214b6e59ba93d4b8ccf57aca158c36429'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A internação, decretada ou mantida pela autoridade judiciária, não pode ser cumprida em estabelecimento prisional. Inexistindo na comarca entidade adequada, o adolescente é imediatamente transferido para a localidade mais próxima. Sendo impossível a pronta transferência, aguarda a remoção em repartição policial, em seção isolada dos adultos e com instalações apropriadas, por prazo não superior a cinco dias, sob pena de responsabilidade.', '["Vedada a internação em estabelecimento prisional.","Transferência imediata para localidade mais próxima.","Espera em repartição policial isolada, por no máximo cinco dias."]'::jsonb, '["Espera em repartição policial: no máximo CINCO dias.","Nunca em presídio."]'::jsonb, 'Sem vaga, o adolescente aguarda a remoção em seção isolada por até cinco dias.', '["Assertiva que fixa em quinze dias a espera em repartição policial erra: são cinco dias."]'::jsonb, '[]'::jsonb, '["Art. 123"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-185' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c3cb377bf4f1a4921a04846ce064a0adbb4e284fdc873f7ed0482f9364e43957'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comparecendo o adolescente, seus pais ou responsável, a autoridade judiciária procede à oitiva dos mesmos, podendo solicitar a opinião de profissional qualificado. Se entender adequada a remissão, ouve o Ministério Público e profere decisão. Sendo o fato grave, passível de internação ou semiliberdade, o juiz, verificando que o adolescente não possui advogado, nomeia defensor e designa audiência em continuação, podendo determinar a realização de diligências e estudo do caso. O advogado constituído ou nomeado apresenta defesa prévia e rol de testemunhas em três dias contados da audiência de apresentação.', '["Oitiva do adolescente e dos pais.","Remissão possível após ouvir o Ministério Público.","Nomeação de defensor nos fatos graves.","Defesa prévia em três dias."]'::jsonb, '["Defesa prévia em TRÊS dias.","Nos fatos graves, a defesa técnica é obrigatória."]'::jsonb, 'O adolescente sem advogado recebe um defensor nomeado pelo juiz.', '["Assertiva que dispensa defesa técnica nos atos graves erra."]'::jsonb, '[]'::jsonb, '["Art. 111"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-186' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c24bb3a83dc336ff617c745ac8b592fb0d5cb094e406da606a9757502343d707'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o adolescente, devidamente notificado, não comparecer injustificadamente à audiência de apresentação, a autoridade judiciária designa nova data, determinando sua condução coercitiva.', '["Nova data com condução coercitiva."]'::jsonb, '["Condução coercitiva do adolescente faltoso."]'::jsonb, 'O adolescente que não vai à audiência é conduzido na data seguinte.', '["Assertiva que decreta a revelia do adolescente que falta sem justificativa erra."]'::jsonb, '[]'::jsonb, '["Art. 184"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-187' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7836a35934c629129b959eac583d6b182990dc384b3860186810aa4fef279e82'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A remissão, como forma de extinção ou suspensão do processo, pode ser aplicada em qualquer fase do procedimento, antes da sentença.', '["Remissão a qualquer tempo antes da sentença."]'::jsonb, '["Limite: antes da SENTENÇA."]'::jsonb, 'O juiz concede remissão durante a audiência, antes de sentenciar.', '["Assertiva que permite a remissão após o trânsito em julgado da sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 126"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-188' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'da795f89d7c742c83c2621e8579b53019c3dc0993f05d858a61712054e9c9095'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade judiciária não aplica qualquer medida quando reconhece na sentença estar provada a inexistência do fato, não haver prova da existência do fato, não constituir o fato ato infracional ou não existir prova de ter o adolescente concorrido para o ato infracional. Nessas hipóteses, estando o adolescente internado, é imediatamente colocado em liberdade.', '["Quatro hipóteses de não aplicação de medida.","Liberdade imediata do internado."]'::jsonb, '["Liberdade IMEDIATA se estiver internado."]'::jsonb, 'Provada a inexistência do fato, o adolescente internado é solto na hora.', '["Assertiva que mantém a internação até o trânsito em julgado da absolvição erra: a liberação é imediata."]'::jsonb, '[]'::jsonb, '["Art. 190"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-189' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '2d2bb45c1513a62b0fe5274ab4ae0cea1f8e9cdacc7b8af6878f83db4bd6801f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A intimação da sentença que aplicar internação ou semiliberdade é feita ao adolescente e ao seu defensor ou, quando não for encontrado o adolescente, a seus pais ou responsável, sem prejuízo do defensor. Sendo outra a medida aplicada, a intimação é feita unicamente na pessoa do defensor. Recaindo a intimação no adolescente, ele deve manifestar se deseja ou não recorrer da sentença.', '["Internação ou semiliberdade: intimação do adolescente e do defensor.","Demais medidas: só o defensor.","O adolescente manifesta se deseja recorrer."]'::jsonb, '["Medidas mais graves: intimação do adolescente E do defensor."]'::jsonb, 'Na sentença de internação, o adolescente é intimado junto com seu defensor.', '["Assertiva que intima só o defensor na sentença de internação erra."]'::jsonb, '[]'::jsonb, '["Art. 189"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5a3af1eecadfce805e385c34a9f0e4b1e3e8b211ff6a29ff1ecedc636bd57918'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A infiltração de agentes de polícia na internet, para investigar crimes sexuais contra crianças e adolescentes previstos no Estatuto e no Código Penal, obedece às seguintes regras: é precedida de autorização judicial circunstanciada e fundamentada, que estabelece os limites da infiltração, ouvido o Ministério Público; dados de conexão ou cadastrais que identifiquem o investigado podem ser requeridos à autoridade judicial; não atende ao princípio da proporcionalidade a infiltração quando a prova puder ser obtida por outros meios; e a infiltração será autorizada pelo prazo de noventa dias, renovável.', '["Infiltração policial na internet para crimes sexuais contra crianças.","Autorização judicial circunstanciada.","Subsidiariedade: só quando a prova não puder ser obtida por outro meio.","Prazo de noventa dias, renovável."]'::jsonb, '["ATUALIZAÇÃO: seção incluída por lei posterior.","Exige AUTORIZAÇÃO JUDICIAL prévia."]'::jsonb, 'O juiz autoriza a infiltração de policial em fórum online para investigar crime sexual contra crianças.', '["Assertiva que dispensa autorização judicial para a infiltração policial na internet erra."]'::jsonb, '[{"termo":"Infiltração de agentes","significado":"Atuação de policial com identidade oculta para colher provas."}]'::jsonb, '["Art. 190-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ddd127aa3ce98aaf3b8494220702cb50cc12dfca3220a11f7b914b6687a6774a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As informações da operação de infiltração são encaminhadas diretamente ao juiz responsável pela autorização, que zela por seu sigilo. Antes da conclusão da operação, o acesso aos autos fica reservado ao juiz, ao Ministério Público e ao delegado de polícia responsável pela operação, para garantir o sigilo das investigações.', '["Informações enviadas diretamente ao juiz.","Sigilo: acesso restrito ao juiz, ao MP e ao delegado."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Acesso reservado a três autoridades."]'::jsonb, 'Só juiz, promotor e delegado acessam os autos da infiltração.', '["Assertiva que permite acesso aos autos da infiltração por qualquer das partes erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '19758b538efe466a594b70784a7d7025d5f238370852bb833fee9e02ed4141ba'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não comete crime o policial que oculta a sua identidade para, pela internet, colher indícios de autoria e materialidade dos crimes sexuais contra crianças e adolescentes previstos no Estatuto e no Código Penal. O agente policial infiltrado que deixar de observar a estrita finalidade da investigação responde pelos excessos praticados.', '["Exclusão de crime do policial que oculta a identidade.","Responde pelos excessos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Responde pelos EXCESSOS."]'::jsonb, 'O policial usa identidade fictícia para colher provas e não responde por isso.', '["Assertiva que isenta o policial infiltrado de qualquer responsabilidade, inclusive por excessos, erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e7e69cd2c01db86546c44da33ee36fe2c7acca7c1c6a04141dd11889be6b70bf'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos de registro e cadastro público podem incluir nos bancos de dados próprios, mediante procedimento sigiloso e requisição da autoridade judicial, as informações necessárias à efetividade da identidade fictícia criada. O procedimento sigiloso é numerado e tombado em livro específico.', '["Inclusão de dados da identidade fictícia em cadastros públicos.","Procedimento sigiloso e livro específico."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O cartório registra a identidade fictícia do policial por ordem judicial.', '["Assertiva que dispensa requisição judicial para a identidade fictícia erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'baed8fd39fcdd44cd3edf58d8c81ca789093fc25ae885d6570e193123bca5737'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concluída a investigação, todos os atos eletrônicos praticados durante a operação devem ser registrados, gravados, armazenados e encaminhados ao juiz e ao Ministério Público, com relatório circunstanciado. Esses atos são reunidos em autos apartados e apensados ao processo criminal juntamente com o inquérito policial, preservando-se a identidade do agente infiltrado.', '["Registro e armazenamento dos atos eletrônicos.","Relatório circunstanciado.","Autos apartados e preservação da identidade do agente."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Preserva-se a identidade do agente."]'::jsonb, 'Ao fim da operação, as conversas gravadas seguem ao juiz e ao Ministério Público.', '["Assertiva que dispensa o registro dos atos eletrônicos da infiltração erra."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-e' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8e3bba2515e14e7a5fc1f4aee667d5a5bba262f73f098d350a07c5a7d641f1a5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É lícita a ronda virtual realizada por órgão de persecução penal mediante software estritamente destinado à identificação e coleta de arquivos disponibilizados em ambientes digitais públicos e relacionados a crimes de violência sexual contra criança ou adolescente. Consideram-se ambientes digitais públicos aqueles em que qualquer pessoa, com ou sem cadastro, visualize conteúdo disponibilizado ao público em geral, como redes peer-to-peer.', '["Ronda virtual lícita.","Software voltado à coleta em ambientes públicos.","Ambientes digitais públicos definidos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Só em ambientes digitais PÚBLICOS."]'::jsonb, 'A polícia usa software para localizar arquivos em redes abertas.', '["Assertiva que autoriza a ronda virtual em comunicações privadas sem ordem judicial erra: é só em ambientes públicos."]'::jsonb, '[]'::jsonb, '["Art. 190-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-190-f' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd41b5ab58dd6ce045cd04906d96564e6372bfb8365d0c1e2dc28fac3e41c1cc6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procedimento de apuração de irregularidades em entidade governamental e não governamental tem início mediante portaria da autoridade judiciária ou representação do Ministério Público ou do Conselho Tutelar, onde conste o resumo dos fatos. Havendo motivo grave, o juiz, ouvido o Ministério Público, pode decretar liminarmente o afastamento provisório do dirigente da entidade, em decisão fundamentada.', '["Início por portaria ou representação.","Afastamento provisório liminar do dirigente por motivo grave."]'::jsonb, '["Quem pode provocar: juiz, MP e Conselho Tutelar."]'::jsonb, 'O juiz afasta provisoriamente o dirigente da entidade acusada de maus-tratos.', '["Assertiva que permite ao Conselho Tutelar afastar o dirigente da entidade erra: o afastamento é judicial."]'::jsonb, '[]'::jsonb, '["Art. 97"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-191' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3984d8781e23cadb0ad8fe5a8350d0a4750c44fc7124cef12e51299970ebed15'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O dirigente da entidade é citado para, no prazo de dez dias, oferecer resposta escrita, podendo juntar documentos e indicar as provas a produzir.', '["Citação do dirigente.","Prazo de dez dias."]'::jsonb, '["Dez dias para resposta."]'::jsonb, 'O dirigente da ONG tem dez dias para se defender.', '["Assertiva que fixa em cinco dias o prazo de resposta do dirigente erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 191"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-192' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '46a53075dd4bea8b88f2777949bd6b8354d18ff6c6bf441652eb73af8d416b2e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentada ou não a resposta, e sendo necessário, a autoridade judiciária designa audiência de instrução e julgamento, intimando as partes. Salvo manifestação em audiência, as partes e o Ministério Público têm cinco dias para oferecer alegações finais, decidindo o juiz em igual prazo. Em caso de afastamento provisório ou definitivo de dirigente de entidade governamental, a autoridade judiciária oficia à autoridade administrativa imediatamente superior, que nomeia substituto interino.', '["Audiência de instrução e julgamento.","Alegações finais em cinco dias e decisão em igual prazo.","Substituto interino do dirigente afastado."]'::jsonb, '["Cinco dias para alegações e cinco para a decisão."]'::jsonb, 'Encerrada a instrução, as partes têm cinco dias para as alegações finais.', '["Assertiva que fixa em dez dias as alegações finais erra: são cinco dias."]'::jsonb, '[]'::jsonb, '["Art. 191"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-193' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4307570aaa044d1bfda9cef3aa22e22faf17e9cae05f96ddac961a1a99e5ed1b'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procedimento para imposição de penalidade administrativa por infração às normas de proteção à criança e ao adolescente começa por representação do Ministério Público ou do Conselho Tutelar, ou por auto de infração elaborado por servidor efetivo ou voluntário credenciado e assinado por duas testemunhas, se possível. No auto de infração podem ser usadas fórmulas impressas, e é facultada a lavratura em forma de boletim e a inclusão de dados essenciais.', '["Início por representação ou auto de infração.","Servidor efetivo ou voluntário credenciado.","Duas testemunhas, se possível."]'::jsonb, '["Auto de infração assinado por duas testemunhas, se possível."]'::jsonb, 'O fiscal lavra auto de infração contra a loja que vendeu bebida a adolescente.', '["Assertiva que exige sempre quatro testemunhas no auto de infração erra."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-194' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '06285ae7d5b5596c1f9b62b599ed98eb2d0413d4cd0da400ac1e10dd482f5202'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O requerido tem prazo de dez dias para apresentar defesa, contado da intimação, que é feita pelo autuante no próprio auto, quando lavrado na presença do requerido; por oficial de justiça ou funcionário habilitado, que entrega cópia do auto; por via postal, com aviso de recebimento; ou por edital, se não for localizado.', '["Defesa em dez dias.","Intimação pelo autuante, oficial de justiça, correio ou edital."]'::jsonb, '["Dez dias para a defesa."]'::jsonb, 'O estabelecimento autuado tem dez dias para apresentar defesa.', '["Assertiva que fixa em cinco dias a defesa do requerido erra: são dez dias."]'::jsonb, '[]'::jsonb, '["Art. 194"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-195' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '13125254fb4453d3173093b80938427c5d0d224bab0d35590b8166b20122e464'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
