insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não sendo apresentada a defesa no prazo legal, a autoridade judiciária dá vista dos autos ao Ministério Público por cinco dias, decidindo em igual prazo.', '["Sem defesa: vista ao Ministério Público por cinco dias.","Decisão em cinco dias."]'::jsonb, '["Cinco dias para o MP e cinco para decidir."]'::jsonb, 'Sem defesa, o promotor tem cinco dias para se manifestar.', '["Assertiva que arquiva o processo por falta de defesa erra."]'::jsonb, '[]'::jsonb, '["Art. 195"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-196' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '315065b4fe8492281cfcd3d870f554c3af1518ff3fb9716279a65ef7c7b5da2f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
