insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apresentada a defesa, a autoridade judiciária procede como no artigo anterior ou, se necessário, designa audiência de instrução e julgamento. Colhida a prova oral, manifestam-se sucessivamente o Ministério Público e o procurador do requerido, por vinte minutos cada um, prorrogáveis por mais dez, a critério da autoridade judiciária, que em seguida profere a sentença.', '["Audiência de instrução, se necessário.","Debates orais: vinte minutos, prorrogáveis por mais dez.","Sentença após os debates."]'::jsonb, '["Vinte minutos para cada parte, prorrogáveis por dez."]'::jsonb, 'O Ministério Público e a defesa têm vinte minutos cada na audiência.', '["Assertiva que fixa em quarenta minutos o tempo de debate de cada parte erra: são vinte, prorrogáveis por dez."]'::jsonb, '[]'::jsonb, '["Art. 196"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-197' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c134e746ab51c822a040077077424c3c2ac4e9a0927171ff0852b6cc2572d4cb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
