insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os postulantes à adoção domiciliados no Brasil apresentam petição inicial com qualificação completa, dados familiares, cópias autenticadas de certidão de nascimento ou casamento ou declaração de união estável, cópias da identidade e do CPF, comprovante de renda e domicílio, atestados de sanidade física e mental, certidão de antecedentes criminais e certidão negativa de distribuição cível.', '["Qualificação e dados familiares.","Documentos pessoais e comprovantes.","Atestados de sanidade e antecedentes."]'::jsonb, '["ATUALIZAÇÃO: procedimento de habilitação incluído pela Lei de Adoção."]'::jsonb, 'O casal junta certidão de antecedentes e atestado de sanidade na habilitação.', '["Assertiva que dispensa antecedentes criminais na habilitação para adoção erra."]'::jsonb, '[]'::jsonb, '["Art. 197-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-197-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'aaf96cb043d8f6133d86d4ec651e9af930c012c7caf302f56d2625881a18a56e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
