insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Intervém obrigatoriamente no feito a equipe interprofissional da Justiça da Infância e da Juventude, que elabora estudo psicossocial para aferir a capacidade e o preparo dos postulantes para uma paternidade ou maternidade responsável. É obrigatória a participação dos postulantes em programa de preparação psicossocial, orientação e estímulo à adoção inter-racial, de crianças maiores ou de adolescentes, com necessidades específicas de saúde ou com deficiência e de grupos de irmãos.', '["Equipe interprofissional obrigatória.","Estudo psicossocial.","Programa obrigatório de preparação."]'::jsonb, '["Participação no programa de preparação é OBRIGATÓRIA."]'::jsonb, 'Os pretendentes frequentam o curso de preparação antes da habilitação.', '["Assertiva que torna facultativo o programa de preparação dos postulantes erra."]'::jsonb, '[]'::jsonb, '["Art. 197-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-197-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1f0d580496de399e8fb7632e429c85ff1d117efdee27a7a9c314ba5c4b0fa801'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Certificada nos autos a conclusão da participação no programa de preparação, a autoridade judiciária, no prazo de quarenta e oito horas, decide sobre as diligências requeridas pelo Ministério Público e determina a juntada do estudo psicossocial, designando, conforme o caso, audiência de instrução e julgamento. Se não houver diligências ou audiência, dá-se vista ao Ministério Público para alegações finais e a sentença é proferida no prazo previsto em lei.', '["Quarenta e oito horas para decidir sobre diligências.","Audiência de instrução quando for o caso.","Alegações finais e sentença."]'::jsonb, '["Quarenta e oito horas após a certificação do programa."]'::jsonb, 'Concluído o curso, o juiz decide sobre diligências em quarenta e oito horas.', '["Assertiva que dispensa o estudo psicossocial na habilitação erra."]'::jsonb, '[]'::jsonb, '["Art. 197-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-197-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '30d3140e3ddcfc4295fc6ce751991f88d52fe37a4f4407da743dbf881f4c8bf4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deferida a habilitação, o postulante é inscrito nos cadastros do art. 50, e sua convocação para a adoção é feita de acordo com a ordem cronológica de habilitação e conforme a disponibilidade de crianças ou adolescentes adotáveis. A ordem cronológica só pode deixar de ser observada nas hipóteses legais, e a recusa sistemática dos postulantes em adotar crianças ou adolescentes indicados implica a reavaliação da habilitação.', '["Inscrição nos cadastros após a habilitação.","Convocação por ordem cronológica.","Recusa sistemática leva à reavaliação."]'::jsonb, '["Ordem CRONOLÓGICA de habilitação."]'::jsonb, 'O casal habilitado há mais tempo é chamado primeiro.', '["Assertiva que permite ignorar a ordem cronológica em qualquer caso erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-197-e' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e8a075b6715c91b16e9aadb1b7d2c047f01d8a860adfe1ad87365684940086d1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O prazo máximo para conclusão da habilitação à adoção é de cento e vinte dias, prorrogável por igual período, mediante decisão fundamentada da autoridade judiciária.', '["Prazo máximo de cento e vinte dias.","Prorrogação por igual período, com fundamentação."]'::jsonb, '["Cento e vinte dias, prorrogáveis por mais cento e vinte."]'::jsonb, 'A habilitação deve ser concluída em cento e vinte dias, com possível prorrogação fundamentada.', '["Assertiva que fixa em sessenta dias o prazo da habilitação erra: são cento e vinte dias."]'::jsonb, '[]'::jsonb, '["Art. 197-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-197-f' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bdac8bc88efb0d49899d757dce4b689d3cdf1cc1daa1f4991db26c82ba572097'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos procedimentos da Justiça da Infância e da Juventude, inclusive na execução das medidas socioeducativas, adota-se o sistema recursal do Código de Processo Civil, com adaptações: os recursos são interpostos independentemente de preparo; em todos os recursos, salvo embargos de declaração, o prazo para o Ministério Público e para a defesa é de dez dias; a apelação é recebida no efeito devolutivo, e o juiz pode conferir efeito suspensivo; e há retratação do juiz em cinco dias, entre outras regras.', '["Sistema recursal do Código de Processo Civil.","Recursos sem preparo.","Prazo de dez dias, salvo embargos de declaração.","Retratação pelo juiz."]'::jsonb, '["ATUALIZAÇÃO: o artigo faz remissão ao antigo Código de Processo Civil; o sistema recursal vigente é o do Código atual, com as adaptações do Estatuto.","Recursos independem de preparo; prazo de dez dias."]'::jsonb, 'A apelação do adolescente é interposta sem pagar custas.', '["Assertiva que exige preparo nos recursos do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 199"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-198' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '161dd0bfd704bd8e66f0edcf180ed4c7230cc061ce36ff68d4bf74c6f77e07f6'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
