insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Contra as decisões proferidas com base no art. 149, que trata de portarias e alvarás judiciais sobre entrada, permanência e participação de crianças e adolescentes, cabe recurso de apelação.', '["Apelação contra decisões do art. 149."]'::jsonb, '["O recurso cabível é a apelação."]'::jsonb, 'A decisão que proíbe a entrada de adolescentes em um evento é apelável.', '["Assertiva que prevê agravo de instrumento contra decisões do art. 149 erra: cabe apelação."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-199' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c4baa2cf41f3a821821dacb7dec0c99ad00dbf38e4e9d655a28cf221ed35e469'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença que defere a adoção produz efeito desde logo, embora sujeita a apelação, que é recebida exclusivamente no efeito devolutivo, salvo se se tratar de adoção internacional ou se houver perigo de dano irreparável ou de difícil reparação ao adotando.', '["Efeito imediato da sentença.","Apelação só no efeito devolutivo.","Exceções: adoção internacional e perigo de dano irreparável."]'::jsonb, '["Apelação NÃO suspende, em regra, a sentença de adoção."]'::jsonb, 'A criança adotada passa a produzir os efeitos da adoção ainda que haja apelação.', '["Assertiva que atribui efeito suspensivo à apelação na adoção nacional comum erra."]'::jsonb, '[]'::jsonb, '["Art. 199-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-199-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'de5d3dc78827484cb9ca3666d91b335def18df678c88a809cb2a4ecb4ec4a189'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
