insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Ministério Público conceder a remissão como forma de exclusão do processo; promover e acompanhar os procedimentos relativos às infrações atribuídas a adolescentes; promover e acompanhar ações de alimentos e os procedimentos de suspensão e destituição do poder familiar, nomeação e remoção de tutores, curadores e guardiões; promover ações de responsabilidade; instaurar procedimentos administrativos e inquéritos civis; inspecionar entidades de atendimento; zelar pelo efetivo respeito aos direitos e garantias legais; e requisitar força policial, entre outras atribuições.', '["Remissão.","Procedimentos relativos a atos infracionais.","Alimentos, destituição do poder familiar e tutela.","Inquérito civil e inspeção de entidades."]'::jsonb, '["Rol de atribuições amplo, com requisição de força policial.","O Ministério Público concede remissão antes do processo."]'::jsonb, 'O promotor visita o abrigo e requisita providências.', '["Assertiva que retira do Ministério Público a legitimidade para promover ações de alimentos de crianças erra."]'::jsonb, '[]'::jsonb, '["Art. 202"]'::jsonb, 'under_review', 'claude'
