select u.id, u.content_sha256, 'As manifestações processuais do representante do Ministério Público devem ser fundamentadas.', '["Fundamentação obrigatória."]'::jsonb, '["Manifestações FUNDAMENTADAS."]'::jsonb, 'O parecer do promotor expõe as razões da conclusão.', '["Assertiva que dispensa fundamentação nas manifestações ministeriais erra."]'::jsonb, '[]'::jsonb, '["Art. 202"]'::jsonb, 'under_review', 'claude'
