insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Regem-se pelo Estatuto as ações de responsabilidade por ofensa aos direitos da criança e do adolescente referentes ao não oferecimento ou à oferta irregular do ensino obrigatório, do atendimento educacional especializado a pessoas com deficiência, do atendimento em creche e pré-escola de zero a cinco anos, do ensino noturno regular, de programas suplementares, de serviço de assistência social, de acesso às ações e serviços de saúde, de escolarização e profissionalização dos adolescentes privados de liberdade, entre outros.', '["Ações de responsabilidade por não oferta de serviços.","Ensino, saúde, creche, assistência social.","Adolescentes privados de liberdade."]'::jsonb, '["Creche e pré-escola: zero a cinco anos.","O rol é exemplificativo, conforme o parágrafo único."]'::jsonb, 'O Ministério Público ajuíza ação para obrigar o município a oferecer vaga em creche.', '["Assertiva que restringe a responsabilidade à oferta irregular do ensino fundamental erra."]'::jsonb, '[]'::jsonb, '["Art. 54"]'::jsonb, 'under_review', 'claude'
