insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os valores das multas revertem ao fundo gerido pelo Conselho dos Direitos da Criança e do Adolescente do respectivo município. As multas não recolhidas até trinta dias após o trânsito em julgado são exigidas por execução promovida pelo Ministério Público, nos mesmos autos, facultada igual iniciativa aos demais legitimados. Enquanto o fundo não for regulamentado, o dinheiro fica depositado em estabelecimento oficial de crédito, em conta com correção monetária.', '["Multas revertem ao fundo municipal.","Execução após trinta dias do trânsito em julgado.","Depósito em conta com correção monetária."]'::jsonb, '["Trinta dias após o trânsito em julgado.","Destino: fundo gerido pelo Conselho de Direitos MUNICIPAL."]'::jsonb, 'A multa aplicada vai para o fundo do município.', '["Assertiva que destina as multas ao fundo estadual erra: é o fundo municipal."]'::jsonb, '[]'::jsonb, '["Art. 154"]'::jsonb, 'under_review', 'claude'
