select u.id, u.content_sha256, 'Transitada em julgado a sentença que impuser condenação ao poder público, o juiz determina a remessa de peças à autoridade competente, para apuração da responsabilidade civil e administrativa do agente a quem se atribua a ação ou omissão.', '["Remessa de peças para apurar a responsabilidade do agente."]'::jsonb, '["Apura-se a responsabilidade do AGENTE."]'::jsonb, 'Condenado o município, o juiz envia peças para apurar a responsabilidade do gestor.', '["Assertiva que isenta o agente público de apuração após a condenação do poder público erra."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
