select u.id, u.content_sha256, 'Qualquer pessoa pode, e o servidor público deve, provocar a iniciativa do Ministério Público, prestando-lhe informações sobre fatos que constituam objeto de ação civil e indicando os elementos de convicção.', '["Qualquer pessoa pode provocar.","O servidor público deve provocar."]'::jsonb, '["Pessoa: PODE; servidor público: DEVE."]'::jsonb, 'O professor comunica ao promotor uma omissão do poder público.', '["Assertiva que torna facultativa para o servidor público a provocação do Ministério Público erra: ele deve."]'::jsonb, '[]'::jsonb, '["Art. 221"]'::jsonb, 'under_review', 'claude'
