insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, no exercício de suas funções, os juízos e tribunais tiverem conhecimento de fatos que possam ensejar ação civil, remetem peças ao Ministério Público para as providências cabíveis.', '["Remessa de peças ao Ministério Público."]'::jsonb, '["Dever dos juízos e tribunais."]'::jsonb, 'O juiz envia ao promotor peças que revelam omissão estatal.', '["Assertiva que dispensa a remessa de peças ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 220"]'::jsonb, 'under_review', 'claude'
