insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público pode instaurar, sob sua presidência, inquérito civil, ou requisitar de qualquer pessoa, organismo público ou particular certidões, informações, exames ou perícias, no prazo que assinalar, que não pode ser inferior a dez dias úteis. Se, esgotadas as diligências, se convencer da inexistência de fundamento para a ação, promove o arquivamento, fundamentadamente, e os autos são remetidos ao Conselho Superior do Ministério Público.', '["Inquérito civil presidido pelo Ministério Público.","Prazo de requisição não inferior a dez dias úteis.","Arquivamento fundamentado, sujeito a revisão."]'::jsonb, '["Prazo mínimo de dez dias úteis.","Arquivamento exige remessa ao Conselho Superior."]'::jsonb, 'O promotor requisita informações com prazo mínimo de dez dias úteis.', '["Assertiva que permite requisição com prazo inferior a dez dias úteis erra."]'::jsonb, '[{"termo":"Inquérito civil","significado":"Procedimento investigatório presidido pelo Ministério Público para apurar fatos de interesse coletivo."}]'::jsonb, '["Art. 224"]'::jsonb, 'under_review', 'claude'
