on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem transporta criança ou adolescente, por qualquer meio, com inobservância das regras sobre viagens dos arts. 83, 84 e 85. A pena é de multa de três a vinte salários de referência, aplicando-se o dobro em caso de reincidência.', '["Transporte sem observar as regras de viagem.","Multa de três a vinte salários de referência."]'::jsonb, '["Alcança o transportador."]'::jsonb, 'A empresa de ônibus que embarca criança sem a autorização exigida pode ser multada.', '["Assertiva que isenta o transportador de responsabilidade erra."]'::jsonb, '[]'::jsonb, '["Art. 83"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-251' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd5f39258438b74e369bfffc59c82c6e2e02b7424d8b0781e00f6ab9c79b9ebaa'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração o responsável por diversão ou espetáculo público que deixa de afixar, em lugar visível e de fácil acesso, à entrada do local, informação destacada sobre a natureza da diversão e a faixa etária especificada no certificado de classificação. A pena é de multa de três a vinte salários de referência, aplicando-se o dobro em caso de reincidência.', '["Omissão de afixar a classificação etária.","Multa de três a vinte salários de referência."]'::jsonb, '["Dobro na reincidência."]'::jsonb, 'O cinema que não indica a faixa etária na entrada é multado.', '["Assertiva que exime o responsável da afixação da classificação erra."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-252' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'da5f61b77c8796915475009eb1afd5b468e8d1a774729163fc1a79e4fa050546'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem anuncia peças teatrais, filmes ou quaisquer representações ou espetáculos sem indicar os limites de idade a que não se recomendem. A pena é de multa de três a vinte salários de referência, duplicada em caso de reincidência, aplicável separadamente à casa de espetáculo e aos órgãos de divulgação ou publicidade.', '["Anúncio sem indicação de idade.","Multa aplicada separadamente à casa e ao órgão de divulgação."]'::jsonb, '["Multa aplicável SEPARADAMENTE à casa e ao veículo de divulgação."]'::jsonb, 'O jornal e o teatro respondem separadamente pelo anúncio sem classificação.', '["Assertiva que aplica uma única multa solidária à casa e ao veículo erra: é aplicada separadamente."]'::jsonb, '[]'::jsonb, '["Art. 74"]'::jsonb, 'under_review', 'claude'
