insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem exibe filme, trailer, peça, amostra ou congênere classificado pelo órgão competente como inadequado às crianças ou adolescentes admitidos ao espetáculo. A pena é de multa de vinte a cem salários de referência; na reincidência, a autoridade pode determinar a suspensão do espetáculo ou o fechamento do estabelecimento por até quinze dias.', '["Exibição inadequada à faixa etária do público.","Multa de vinte a cem salários de referência.","Suspensão ou fechamento por até quinze dias na reincidência."]'::jsonb, '["Quinze dias na reincidência."]'::jsonb, 'O cinema que exibe trailer impróprio antes de filme infantil é multado.', '["Assertiva que prevê fechamento de sessenta dias erra: são até quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 75"]'::jsonb, 'under_review', 'claude'
