insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração o responsável pelo estabelecimento ou o empresário que deixa de observar o que dispõe a lei sobre o acesso de criança ou adolescente aos locais de diversão ou sobre sua participação no espetáculo. A pena é de multa de três a vinte salários de referência; em caso de reincidência, a autoridade judiciária pode determinar o fechamento do estabelecimento por até quinze dias.', '["Acesso irregular a locais de diversão.","Multa e fechamento por até quinze dias na reincidência."]'::jsonb, '["Quinze dias de fechamento na reincidência."]'::jsonb, 'A casa de sinuca que admite adolescentes é multada.', '["Assertiva que isenta o empresário que aceita adolescente sem acompanhante erra."]'::jsonb, '[]'::jsonb, '["Art. 80"]'::jsonb, 'under_review', 'claude'
