insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração a autoridade competente que deixa de providenciar a instalação e operacionalização dos cadastros de adoção e de acolhimento. A pena é de multa de mil a três mil reais. Incorre nas mesmas penas a autoridade que deixa de cadastrar crianças e adolescentes adotáveis, pessoas ou casais habilitados e crianças em acolhimento institucional ou familiar.', '["Omissão em instalar os cadastros.","Multa de mil a três mil reais.","Omissão em cadastrar crianças e pretendentes."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei de Adoção.","Multa de mil a três mil reais."]'::jsonb, 'A autoridade que não cadastra as crianças adotáveis sofre multa.', '["Assertiva que prevê pena de detenção para a omissão em instalar os cadastros erra: é multa."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
