insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração o médico, enfermeiro ou dirigente de estabelecimento de atenção à saúde de gestante que deixa de efetuar o imediato encaminhamento à autoridade judiciária de caso de mãe ou gestante interessada em entregar o filho para adoção. A pena é de multa de mil a três mil reais. Incorre na mesma pena o funcionário de programa oficial ou comunitário de convivência familiar que deixa de efetuar a comunicação.', '["Omissão do encaminhamento imediato ao juiz.","Multa de mil a três mil reais.","Estende-se ao funcionário de programa de convivência familiar."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei de Adoção.","Encaminhamento IMEDIATO à autoridade judiciária."]'::jsonb, 'O médico que sabe do interesse da gestante em entregar o filho e nada comunica é multado.', '["Assertiva que isenta o funcionário de programa comunitário da comunicação erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-258-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1059e2bc7b8d7f0ef85f9892ce66c2f6e6092698792d466d0628e8bbae99b7e2'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem descumpre a proibição de vender bebida alcoólica a criança ou adolescente, prevista no inciso II do art. 81. A pena é de multa de três mil a dez mil reais, com a medida administrativa de interdição do estabelecimento comercial até o recolhimento da multa aplicada.', '["Venda de bebida alcoólica a criança ou adolescente.","Multa de três mil a dez mil reais.","Interdição até o recolhimento da multa."]'::jsonb, '["ATUALIZAÇÃO: infração administrativa incluída por lei posterior.","Interdição até o recolhimento da multa."]'::jsonb, 'O comércio que vende cerveja a adolescente é multado e pode ser interditado.', '["Assertiva que dispensa a interdição enquanto a multa não for paga erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
