insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União, no prazo de noventa dias contados da publicação do Estatuto, elaborará projeto de lei dispondo sobre a criação ou adaptação de seus órgãos às diretrizes da política de atendimento. Compete aos estados e municípios promoverem a adaptação de seus órgãos e programas às diretrizes e princípios da lei.', '["Prazo de noventa dias para a União.","Adaptação por estados e municípios."]'::jsonb, '["Dispositivo de transição, já cumprido em sua maior parte."]'::jsonb, 'Estados e municípios adaptaram seus programas ao Estatuto.', '["Assertiva que atribui só à União a adaptação dos órgãos erra: estados e municípios também adaptam os seus."]'::jsonb, '[]'::jsonb, '["Art. 88"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-259' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '06e2c81d66d83d675b33254545abe8595d569a9a6e7e84a5e45c2fedcb518928'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
