insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As doações podem ser efetuadas em espécie ou em bens. As doações em espécie devem ser depositadas em conta específica, em instituição financeira pública, vinculada ao respectivo fundo.', '["Doação em espécie ou em bens.","Conta específica em instituição financeira pública."]'::jsonb, '["Conta ESPECÍFICA em instituição financeira PÚBLICA."]'::jsonb, 'A doação em dinheiro é depositada na conta do fundo no banco público.', '["Assertiva que permite depósito em banco privado erra."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-c' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cb2587c69ccfc1dcaee03ea5dfdb3ec1cdccbd87dacf5e6f46ab10506da28d75'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos responsáveis pela administração das contas dos Fundos devem emitir recibo em favor do doador, assinado por pessoa competente e pelo presidente do Conselho correspondente, especificando número de ordem, dados do emitente e do doador, data e valor efetivamente recebido e o ano-calendário da doação.', '["Recibo assinado pelo responsável e pelo presidente do Conselho.","Dados do emitente, do doador, da data, do valor e do ano-calendário."]'::jsonb, '["Recibo com assinatura do presidente do Conselho."]'::jsonb, 'O doador recebe recibo do fundo para comprovar a dedução.', '["Assertiva que dispensa a assinatura do presidente do Conselho no recibo erra."]'::jsonb, '[]'::jsonb, '["Art. 260-F"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-d' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a3286fdefe11789a5fedf5f24478376b5bfa2414c0f371d67b5b28787c5a6e6e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na doação em bens, o doador deve comprovar a propriedade dos bens, baixá-los na declaração de bens e direitos (pessoa física) ou na escrituração (pessoa jurídica), e considerar como valor dos bens doados, para a pessoa física, o valor constante da última declaração de imposto de renda, desde que não exceda o valor de mercado, e, para a pessoa jurídica, o valor contábil.', '["Comprovação de propriedade.","Baixa na declaração ou na escrituração.","Valor da doação conforme a natureza do doador."]'::jsonb, '["Valor: o da última declaração (pessoa física) ou contábil (pessoa jurídica)."]'::jsonb, 'A empresa doa equipamento e considera o valor contábil do bem.', '["Assertiva que adota sempre o valor de mercado como valor da doação em bens erra."]'::jsonb, '[]'::jsonb, '["Art. 260-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-e' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '81b2c47178d54e86f0c29eaa20ed59a0a59322922954444eab858981ed5e2b79'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os documentos referentes ao recibo e à doação em bens devem ser mantidos pelo contribuinte por um prazo de cinco anos, para fins de comprovação da dedução perante a Receita Federal do Brasil.', '["Guarda dos documentos por cinco anos."]'::jsonb, '["Cinco anos."]'::jsonb, 'O doador guarda o recibo por cinco anos para comprovar a dedução.', '["Assertiva que fixa em dois anos a guarda dos documentos erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 260-D"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-f' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c32cd8b6211b6a86c1fffc29a9aaa01362e855716b0f101a78e4de6518c590bb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos responsáveis pela administração das contas dos Fundos devem manter conta bancária específica destinada exclusivamente a gerir os recursos do Fundo, manter controle das doações recebidas e informar anualmente à Receita Federal as doações recebidas mês a mês, identificando por doador o nome, o CNPJ ou CPF e o valor doado, em espécie ou em bens.', '["Conta bancária exclusiva.","Controle das doações.","Informação anual à Receita Federal."]'::jsonb, '["Informação anual à Receita, mês a mês."]'::jsonb, 'O fundo informa à Receita todas as doações do ano, por doador.', '["Assertiva que dispensa a informação à Receita Federal erra."]'::jsonb, '[]'::jsonb, '["Art. 260-H"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-g' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '162db2e9a06c5d9f16ca85782e4fcce2703929a59eea58ac5b2edbbc4b83f53d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de descumprimento das obrigações previstas no art. 260-G, a Secretaria da Receita Federal do Brasil dá conhecimento do fato ao Ministério Público.', '["Comunicação ao Ministério Público pela Receita Federal."]'::jsonb, '["Quem comunica é a Receita Federal."]'::jsonb, 'A Receita avisa o promotor sobre a omissão do fundo.', '["Assertiva que atribui ao Conselho Tutelar a fiscalização das informações ao Fisco erra."]'::jsonb, '[]'::jsonb, '["Art. 260-G"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-h' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0eaed82b5a1266ae0ff05b476bc4935505e1ec5a8f2e3163c845508797a6e938'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Conselhos dos Direitos da Criança e do Adolescente divulgam amplamente à sociedade o calendário de suas reuniões, as ações prioritárias para aplicação das políticas, os requisitos para a apresentação de projetos a serem beneficiados com recursos dos Fundos, a relação dos projetos aprovados em cada ano e o valor dos recursos previstos, entre outras informações.', '["Transparência dos Conselhos.","Divulgação de reuniões, prioridades e projetos aprovados."]'::jsonb, '["Dever de ampla divulgação."]'::jsonb, 'O Conselho publica a lista dos projetos beneficiados no ano.', '["Assertiva que dispensa a divulgação dos projetos aprovados erra."]'::jsonb, '[]'::jsonb, '["Art. 260-J"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-i' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '79e8c84ccd5ac4966f08feca5c9ce1d5278c5cb27432d52c2c065bf62c3cc96f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Ministério Público determina, em cada Comarca, a forma de fiscalização da aplicação dos incentivos fiscais. O descumprimento dos arts. 260-G e 260-I sujeita os infratores a ação judicial proposta pelo Ministério Público, que pode atuar de ofício, a requerimento ou representação de qualquer cidadão.', '["Fiscalização definida pelo Ministério Público.","Ação judicial por descumprimento.","Atuação de ofício ou por representação de cidadão."]'::jsonb, '["Qualquer cidadão pode representar ao Ministério Público."]'::jsonb, 'O cidadão representa ao promotor contra o conselho que não divulga os projetos.', '["Assertiva que exige provocação de órgão público para a atuação do Ministério Público erra: pode atuar de ofício."]'::jsonb, '[]'::jsonb, '["Art. 260-I"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-j' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bc5ee076356d3c35fe4fc60ab77cf5410419ddbeb595a68b70afd64900bb34c5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Secretaria de Direitos Humanos da Presidência da República encaminha à Receita Federal, até trinta e um de outubro de cada ano, arquivo eletrônico com a relação atualizada dos Fundos dos Direitos da Criança e do Adolescente, com os números de CNPJ e das contas bancárias específicas em instituições financeiras públicas.', '["Envio anual à Receita Federal até trinta e um de outubro.","Relação dos Fundos com CNPJ e contas bancárias."]'::jsonb, '["Prazo: até trinta e um de outubro de cada ano.","A estrutura administrativa citada foi reorganizada desde a edição da lei."]'::jsonb, 'Cada ano, o órgão federal competente envia à Receita a lista de fundos habilitados a receber doações.', '["Assertiva que fixa o envio até trinta de junho erra: é até trinta e um de outubro."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-k' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '03cc3a954233cc046e498d070853ae6965ae3157342e9172be828bfe0c482e8a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

