select u.id, u.content_sha256, 'A Secretaria da Receita Federal do Brasil expede as instruções necessárias à aplicação do disposto nos arts. 260 a 260-K.', '["Regulamentação pela Receita Federal."]'::jsonb, '["Competência regulamentar da Receita."]'::jsonb, 'A Receita edita normas sobre a dedução das doações.', '["Assertiva que atribui ao Conselho Tutelar a regulamentação da dedução erra."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-l' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e536600dabcb600d6ee6f5f0bd6cea7aa1ee5e00b0703cccda3672242e9fa738'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na falta dos Conselhos Municipais dos Direitos da Criança e do Adolescente, os registros, inscrições e alterações de entidades e programas são efetuados perante a autoridade judiciária da comarca a que pertencer a entidade. A União fica autorizada a repassar aos estados e municípios, e os estados aos municípios, os recursos referentes aos programas, tão logo estejam criados os conselhos dos direitos nos respectivos níveis.', '["Registro perante o juiz na falta do Conselho Municipal.","Repasses condicionados à criação dos Conselhos."]'::jsonb, '["Dispositivo transitório: supre a ausência do Conselho Municipal."]'::jsonb, 'Sem Conselho Municipal, a entidade registra-se na comarca.', '["Assertiva que dispensa o registro da entidade na falta do Conselho Municipal erra."]'::jsonb, '[]'::jsonb, '["Art. 91"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-261' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'dfad165ddf5ef65b9cbf16f5592d479ac0283a283275030ba585148f8d06479d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Enquanto não instalados os Conselhos Tutelares, as atribuições a eles conferidas são exercidas pela autoridade judiciária.', '["Suprimento transitório pelo juiz."]'::jsonb, '["Dispositivo transitório."]'::jsonb, 'Sem Conselho Tutelar no município, o juiz exerce as atribuições.', '["Assertiva que paralisa a proteção enquanto não instalado o Conselho Tutelar erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-262' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '050ce7c7b75fa7bf103980806649f9037074435b710b971a9b2272feb55441e4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Altera dispositivos do Código Penal, como o aumento de pena no homicídio e na lesão corporal quando a vítima é menor, entre outras mudanças, que hoje constam do próprio Código Penal e das leis específicas.', '["Alterações do Código Penal feitas pelo Estatuto."]'::jsonb, '["Dispositivo de alteração; consulte o Código Penal vigente.","ATUALIZAÇÃO: o Código Penal foi alterado diversas vezes depois."]'::jsonb, 'Os aumentos de pena por vítima menor passaram a constar do Código Penal.', '["Assertiva que aplica o texto alterador do art. 263 em substituição ao Código Penal vigente erra."]'::jsonb, '[]'::jsonb, '["Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-263' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '70e37c5155e21f5a4b7fe06af8c9870bbca627d00beb387f8ee0533ee6514509'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Acrescenta ao art. 102 da Lei de Registros Públicos o item que determina a averbação da perda e da suspensão do poder familiar, então chamado de pátrio poder.', '["Averbação da perda e da suspensão do poder familiar."]'::jsonb, '["Terminologia atualizada: hoje se diz poder familiar."]'::jsonb, 'A sentença de destituição é averbada no registro de nascimento.', '["Assertiva que dispensa a averbação da perda do poder familiar erra."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
