insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A Imprensa Nacional e demais gráficas da União, da administração direta ou indireta, inclusive fundações mantidas pelo poder público federal, promovem edição popular do texto integral do Estatuto, posto à disposição das escolas e das entidades de atendimento e de defesa dos direitos da criança e do adolescente.', '["Edição popular do Estatuto.","Distribuição a escolas e entidades."]'::jsonb, '["Dispositivo de divulgação."]'::jsonb, 'A Imprensa Nacional distribui o texto do Estatuto às escolas.', '["Assertiva que restringe a divulgação às entidades privadas erra."]'::jsonb, '[]'::jsonb, '["Art. 265-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-265' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '592d384063835dff9671d0558c4dc9aebe49c1fc23da834f0d4a701e869753d9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público faz periodicamente ampla divulgação dos direitos da criança e do adolescente nos meios de comunicação social. A divulgação é veiculada em linguagem clara, compreensível e adequada a crianças e adolescentes, especialmente às crianças com idade inferior a seis anos.', '["Divulgação periódica nos meios de comunicação.","Linguagem adequada, especialmente a crianças menores de seis anos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Atenção às crianças menores de seis anos."]'::jsonb, 'A campanha pública usa linguagem adequada aos pequenos.', '["Assertiva que dispensa a adequação da linguagem ao público infantil erra."]'::jsonb, '[]'::jsonb, '["Art. 265"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-265-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b543bb4d9b5a327e31586a19206030396991b4dfa34fa83b33cd7f7fd83d9143'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lei entrou em vigor noventa dias após sua publicação. Durante o período de vacância deveriam ser promovidas atividades e campanhas de divulgação e esclarecimentos acerca do disposto na lei.', '["Vigência noventa dias após a publicação.","Campanhas durante a vacância."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'O Estatuto começou a valer noventa dias depois de publicado.', '["Assertiva que fixa a vigência imediata na data da publicação erra."]'::jsonb, '[]'::jsonb, '["Art. 267"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-266' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bbbdb93d12efc3c5e97c50f48f86464092f529f43823f05e446350523ec0536f'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Revogam-se as leis anteriores sobre a matéria, entre elas o antigo Código de Menores, e as demais disposições em contrário.', '["Revogação do Código de Menores.","Revogação das disposições contrárias."]'::jsonb, '["Marca a substituição do antigo sistema pela proteção integral."]'::jsonb, 'O Código de Menores deixou de valer com o Estatuto.', '["Assertiva que mantém o Código de Menores em vigor ao lado do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-267' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '02e20c15dcad0c5f9a59eb8b25ebbb1e4fd6bded7fecfab7c524e1acf20fd943'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
