on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Submeter criança ou adolescente sob sua autoridade, guarda ou vigilância a vexame ou constrangimento é a conduta do art. 232, com detenção de seis meses a dois anos. Este artigo permanece vigente no texto oficial.', '["A relação de autoridade, guarda ou vigilância integra o tipo."]'::jsonb, '["Conferência editorial em 11/10/2026; essa data não indica alteração legislativa ou início de vigência.", "A Lei 9.455/1997 revogou o art. 233, não o art. 232. Tortura tem requisitos próprios: não transforme automaticamente qualquer constrangimento no crime da Lei de Tortura."]'::jsonb, 'Um responsável submete adolescente sob sua guarda a situação vexatória: examine os elementos do art. 232, sem pressupor os requisitos de outro tipo. Variação: O enunciado descreve tortura com os requisitos específicos da Lei 9.455: compare os tipos em suas fontes, sem afirmar que o art. 232 foi revogado.', '["A Lei de Tortura revogou o art. 232? Não; seu art. 4º revogou o art. 233 do ECA. O art. 232 continua no texto vigente."]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'under_review', 'reviewed-draft'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-232' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7378844b0fd40f58be832fd0dd48ee32b8dfda00cd9fb18e70f797b9061ff642'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;
